        (function () {
            function upd() {
                var el = document.getElementById('netStatus');
                if (!el) return;
                var on = navigator.onLine !== false;
                var dots = document.querySelectorAll('.net-dot');
                for (var i = 0; i < dots.length; i++) {
                    dots[i].classList.toggle('online', on);
                    dots[i].classList.toggle('offline', !on);
                    dots[i].title = on ? 'Online' : 'Offline';
                }
                el.className = 'net-status ' + (on ? 'on' : 'off');
                el.textContent = on ? '\u25CF You are online \u2013 all features will work.'
                                    : '\u25CF You are offline \u2013 some features are limited (see the list above).';
            }
            upd();
            document.addEventListener('DOMContentLoaded', upd);
            window.addEventListener('load', upd);
            window.addEventListener('online', upd);
            window.addEventListener('offline', upd);
        })();
        
;

/* ===== script block from original line 4570 ===== */
        // ===== Custom in-app dialog system (replaces window.alert/confirm/prompt) =====
        let customDialogResolve = null;
        // State for the mobile browser / WebView back-button exit confirmation.
        let appExitGuardActive = false;
        let appExitPromptOpen = false;
        let appExitConfirmed = false;

        function _openCustomDialog(mode, title, iconClass, message, { showInput = false, defaultValue = '', okLabel = 'OK', cancelLabel = 'Cancel', showCancel = false } = {}) {
            return new Promise((resolve) => {
                customDialogResolve = resolve;
                const modal = document.getElementById('customDialogModal');
                modal.dataset.mode = mode;
                document.getElementById('customDialogTitle').innerHTML = `<i class="fa-solid ${iconClass}"></i> ${title}`;
                document.getElementById('customDialogMessage').textContent = message;

                const input = document.getElementById('customDialogInput');
                input.style.display = showInput ? 'block' : 'none';
                input.value = showInput ? defaultValue : '';

                document.getElementById('customDialogCancelBtn').style.display = showCancel ? 'inline-flex' : 'none';
                document.getElementById('customDialogCancelBtn').textContent = cancelLabel;
                document.getElementById('customDialogOkBtn').textContent = okLabel;

                modal.classList.add('active');

                if (showInput) {
                    setTimeout(() => { input.focus(); input.select(); }, 50);
                }
            });
        }

        function showCustomAlert(message, title = 'Notice') {
            return _openCustomDialog('alert', title, 'fa-circle-info', message, { okLabel: 'OK', showCancel: false });
        }

        function showCustomConfirm(message, title = 'Please Confirm', { okLabel = 'Yes', cancelLabel = 'Cancel' } = {}) {
            return _openCustomDialog('confirm', title, 'fa-triangle-exclamation', message, { okLabel, cancelLabel, showCancel: true });
        }

        function showCustomPrompt(message, defaultValue = '', title = 'Enter Value') {
            return _openCustomDialog('prompt', title, 'fa-pen', message, { showInput: true, defaultValue, okLabel: 'OK', showCancel: true });
        }

        function confirmCustomDialogOk() {
            const modal = document.getElementById('customDialogModal');
            const mode = modal.dataset.mode;
            let result;
            if (mode === 'prompt') {
                result = document.getElementById('customDialogInput').value;
            } else {
                result = true;
            }
            resolveCustomDialog(result);
        }

        function resolveCustomDialog(value) {
            const modal = document.getElementById('customDialogModal');
            const mode = modal.dataset.mode;
            modal.classList.remove('active');
            if (customDialogResolve) {
                if (value === null) {
                    customDialogResolve(mode === 'confirm' ? false : null);
                } else {
                    customDialogResolve(value);
                }
                customDialogResolve = null;
            }
        }
