        function ensureMindspaceAutoPost() {
            cleanupMindspaceAutoPosts();
            if (!mindspaceAutoPosts.length) {
                const quote = motivationalQuotes[Math.floor(Math.random() * motivationalQuotes.length)];
                mindspaceAutoPosts.unshift({ id: 'ms-' + Date.now(), title: 'MindSpace Daily Motivation', content: quote.replace(/^\"|\"$/g, ''), timestamp: Date.now(), expiresAt: Date.now() + MINDSPACE_POST_TTL });
                localStorage.setItem('mindspaceAutoPosts', JSON.stringify(mindspaceAutoPosts));
            }
            if (mindspaceExpiryTimer) clearTimeout(mindspaceExpiryTimer);
            const nextExpiry = mindspaceAutoPosts.reduce((min, p) => Math.min(min, p.expiresAt || (p.timestamp + MINDSPACE_POST_TTL)), Infinity);
            if (isFinite(nextExpiry)) {
                mindspaceExpiryTimer = setTimeout(() => {
                    cleanupMindspaceAutoPosts();
                    ensureMindspaceAutoPost();
                    if (document.getElementById('feedSection')?.style.display !== 'none') renderReviewerFeed();
                }, Math.max(1000, nextExpiry - Date.now() + 1000));
            }
        }
