        /* ===== STABLE POST DATE & TIME =====
           Every post gets ONE permanent timestamp when it is created.
           It only changes when the post is edited and saved again. */
        function formatPostDateTime(ts) {
            const d = new Date(ts);
            return d.toLocaleDateString() + ' ' + d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
        }

        function ensureStableTimestamps() {
            const base = Date.now();
            const sets = [
                ['savedCodesList', savedCodes],
                ['stickyNotesList', stickyNotesList],
                ['journalPostsList', journalPostsList],
                ['biblePostsList', biblePostsList]
            ];
            sets.forEach(([storageKey, list]) => {
                let changed = !localStorage.getItem(storageKey);
                list.forEach((it, idx) => {
                    if (!it || typeof it !== 'object') return;
                    if (typeof it.date === 'string' && /\(Edited\)/i.test(it.date) && !it.edited) {
                        it.edited = true;
                        changed = true;
                    }
                    if (typeof it.timestamp === 'number' && isFinite(it.timestamp) && it.timestamp > 0) return;
                    let ts = Date.parse(String(it.date || '').replace(/\s*\(Edited\)\s*$/i, ''));
                    if (!isFinite(ts)) ts = base - (idx * 60000);
                    it.timestamp = ts;
                    changed = true;
                });
                if (changed) localStorage.setItem(storageKey, JSON.stringify(list));
            });
        }
        ensureStableTimestamps();

