        const themeDisplayNames = {
            brown: 'Brown / Vintage', green: 'Emerald Green', blue: 'Royal Blue', purple: 'Deep Purple',
            orange: 'Warm Orange', red: 'Crimson Red', teal: 'Teal / Cyan', navy: 'Midnight Navy',
            pink: 'Rose Pink', gray: 'Charcoal Gray', yellow: 'Sunny Yellow', glass: 'Liquid Glass'
        };
        const themeOrder = ['brown','green','blue','purple','orange','red','teal','navy','pink','gray','yellow','glass'];
        let themeOptionsWarm = false;

        function renderThemeColorOptions() {
            const grid = document.getElementById('themeOptionsGrid');
            if (!grid) return;
            grid.innerHTML = themeOrder.map(key => {
                const t = themePresets[key];
                const vars = `--preview-bg:${t.bgMain};--preview-card:${t.cardBg};--preview-box:${t.boxBg};--preview-border:${t.boxBorder};--preview-accent:${t.accent};--preview-dark:${t.textDark};`;
                const unavailable = performanceMode !== 'off' && key === 'glass';
                const action = unavailable ? 'disabled title="Not supported while Performance Mode is active"' : `onclick="selectThemeColor('${key}')"`;
                const label = unavailable ? `${themeDisplayNames[key]} — unavailable in Performance Mode` : themeDisplayNames[key];
                return `<button type="button" class="theme-option-card ${key === currentThemeColorKey ? 'selected' : ''}" style="${vars}" ${action} aria-label="${label}">
                    <div class="theme-preview-window"><div class="theme-preview-banner"></div><div class="theme-preview-content"><div class="theme-preview-title"></div><div class="theme-preview-row"><div class="theme-preview-box"></div><div class="theme-preview-box"></div></div><div class="theme-preview-button"></div></div></div>
                    <div class="theme-option-name"><span>${label}</span><i class="fa-solid fa-circle-check"></i></div>
                </button>`;
            }).join('');
            themeOptionsWarm = true;
        }
        function openThemeColorPrompt() {
            const modal = document.getElementById('themeColorModal');
            if (!modal) return;
            if (!themeOptionsWarm) renderThemeColorOptions();
            modal.classList.add('active');
        }
        function selectThemeColor(key) {
            if (!themePresets[key]) return;
            if (performanceMode !== 'off' && key === 'glass') {
                showCustomAlert('Liquid Glass is unavailable while Performance Mode is active. Set Performance Mode to Off to use it.', 'Liquid Glass unavailable');
                return;
            }
            const preview = showThemeChangePreview(key);
            closeThemeColorPrompt();
            const setProgress = value => {
                const percent = Math.max(0, Math.min(100, Math.round(value)));
                const progress = preview.querySelector('.theme-preview-progress');
                const track = preview.querySelector('.theme-preview-progress-track');
                const fill = preview.querySelector('.theme-preview-progress-fill');
                if (progress) progress.textContent = `${percent}%`;
                if (track) track.setAttribute('aria-valuenow', String(percent));
                if (fill) fill.style.width = `${percent}%`;
            };
            setProgress(12);
            /* Let the preview paint first, then measure/apply the real theme update. */
            requestAnimationFrame(() => {
                setProgress(35);
                requestAnimationFrame(() => {
                    const applyStartedAt = performance.now();
                    if (document.documentElement.getAttribute('data-theme') === 'dark') toggleTheme(false);   // auto Light Mode kapag nagpalit ng theme color; sariling color preview na ang ipinapakita
                    applyThemeColor(key, false);
                    const applyDuration = performance.now() - applyStartedAt;
                    setProgress(100);
                    document.querySelectorAll('#themeOptionsGrid .theme-option-card').forEach(card => card.classList.toggle('selected', card.getAttribute('aria-label') === themeDisplayNames[key]));
                    /* Fast systems reach 100% immediately; slower updates still remain on-screen before closing. */
                    window.setTimeout(() => {
                        preview.classList.add('closing');
                        window.setTimeout(() => preview.remove(), 760);
                    }, Math.max(3000, Math.min(3600, 3000 + applyDuration)));
                });
            });
        }
        function closeThemeColorPrompt() {
            const modal = document.getElementById('themeColorModal');
            if (modal) modal.classList.remove('active');
        }

        let fullCodeViewerBusy = false;
        let fullCodeRestartTimer = null;
        let fullCodeScrollHandler = null;
        function setFullCodeLoading(progress, status, subtitle) {
            const screen = document.getElementById('fullCodeLoadingScreen');
            const bar = document.getElementById('fullCodeLoadingBarFill');
            const statusEl = document.getElementById('fullCodeLoadingStatus');
            const subtitleEl = document.getElementById('fullCodeLoadingSubtitle');
            if (document.body) document.body.classList.add('full-code-loading-active');
            if (screen) screen.classList.add('active');
            if (bar) bar.style.width = Math.max(0, Math.min(100, Number(progress) || 0)) + '%';
            if (statusEl && status) statusEl.textContent = status;
            if (subtitleEl && subtitle) subtitleEl.textContent = subtitle;
        }
        function nextCodePaint() {
            return new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)));
        }
        async function openFullCodeViewer() {
            const viewer = document.getElementById('fullCodeViewer');
            const gutter = document.getElementById('fullCodeGutter');
            const textBox = document.getElementById('fullCodeText');
            const modal = document.getElementById('fullCodeModal');
            const loading = document.getElementById('fullCodeLoadingScreen');
            if (!viewer || !gutter || !textBox || !modal || !loading || fullCodeViewerBusy) return;
            fullCodeViewerBusy = true;
            clearTimeout(fullCodeRestartTimer);
            modal.classList.remove('active');
            closeOtherPopups('fullCodeModal');
            setFullCodeLoading(8, 'Closing MindSpace panels...', 'Preparing the complete MindSpace code...');
            await nextCodePaint();
            setFullCodeLoading(28, 'Clearing the previous code view...', 'Loading every part of MindSpace...');
            gutter.textContent = ''; textBox.textContent = '';
            await nextCodePaint();
            setFullCodeLoading(48, 'Collecting the full source...', 'Please wait while the complete code is prepared.');
            const source = '<!DOCTYPE html>\n' + getInfoHeaderComment('<!DOCTYPE html>\n' + document.documentElement.outerHTML) + document.documentElement.outerHTML;
            await nextCodePaint();
            setFullCodeLoading(68, 'Formatting line numbers...', 'Almost ready...');
            const total = source.split('\n').length;
            const nums = new Array(total);
            for (let i = 0; i < total; i++) nums[i] = i + 1;
            gutter.textContent = nums.join('\n');
            setFullCodeLoading(82, 'Highlighting the complete source...', 'Building the Full MindSpace Code screen...');
            /* Highlighting a 1.6MB+ source synchronously can freeze phones. Keep the
               complete source intact, but use fast plain-text rendering on mobile or
               reduced-performance mode. Desktop keeps syntax highlighting. */
            const useFastCodeMode = document.body.classList.contains('mobile-mode') ||
                document.documentElement.getAttribute('data-performance-mode') !== 'off' ||
                window.innerWidth <= 720;
            viewer.classList.toggle('fast-mobile-mode', useFastCodeMode);
            if (useFastCodeMode) {
                textBox.textContent = source;
                setFullCodeLoading(86, 'Using fast mobile code rendering...', 'Loading the complete source without freezing the phone.');
            } else if (window.hljs && window.hljs.getLanguage('xml')) {
                textBox.innerHTML = window.hljs.highlight(source, { language: 'xml', ignoreIllegals: true }).value;
            } else {
                textBox.textContent = source;
            }
            viewer.scrollTop = 0; viewer.scrollLeft = 0;
            await nextCodePaint();
            const scrollBar = document.getElementById('fullCodeScrollProgress');
            const scrollTrack = scrollBar && scrollBar.parentElement;
            const screenStatus = document.getElementById('fullCodeScreenStatus');
            const updateFullCodeScrollProgress = () => {
                const max = Math.max(0, viewer.scrollHeight - viewer.clientHeight);
                const percent = max ? Math.round((viewer.scrollTop / max) * 100) : 100;
                if (scrollBar) scrollBar.style.width = percent + '%';
                if (scrollTrack) scrollTrack.setAttribute('aria-valuenow', String(percent));
                if (screenStatus) screenStatus.textContent = max ? `Full code loaded — viewing ${percent}%` : 'Full code loaded.';
                viewer.classList.add('is-scrolling');
                clearTimeout(viewer.__fullCodeScrollTimer);
                viewer.__fullCodeScrollTimer = setTimeout(() => viewer.classList.remove('is-scrolling'), 220);
            };
            if (fullCodeScrollHandler) viewer.removeEventListener('scroll', fullCodeScrollHandler);
            fullCodeScrollHandler = updateFullCodeScrollProgress;
            viewer.addEventListener('scroll', fullCodeScrollHandler, { passive: true });
            updateFullCodeScrollProgress();
            setFullCodeLoading(100, 'Full code loaded.', 'Full MindSpace Code');
            await new Promise(resolve => setTimeout(resolve, 420));
            loading.classList.remove('active');
            if (document.body) document.body.classList.remove('full-code-loading-active');
            modal.classList.add('active');
            fullCodeViewerBusy = false;
        }
        function closeFullCodeViewer() {
            const modal = document.getElementById('fullCodeModal');
            const loading = document.getElementById('fullCodeLoadingScreen');
            if (!modal || (!modal.classList.contains('active') && !fullCodeViewerBusy)) return;
            modal.classList.remove('active');
            fullCodeViewerBusy = false;
            setFullCodeLoading(100, 'Restarting MindSpace...', 'Returning to your workspace...');
            clearTimeout(fullCodeRestartTimer);
            fullCodeRestartTimer = setTimeout(() => { appExitConfirmed = true; window.location.reload(); }, 650);
        }
        /* ===== v1.68: CREDITS & INFORMATION + isang pop up lang sa isang pagkakataon ===== */
        // ====================================================================
        //  ★ VERSION: dito lang palitan (hal. '1.70' -> '1.71'). Kusa nang
        //    magbabago ang tab title, Credits & Information, at code header.
        // ====================================================================
        const MINDSPACE_INFO = {
            name: 'MindSpace',
            version: '2.58', /* Dito magpalit ng version */
            creator: 'Aldrin Pagangpang Yancha',
            background: 'College Student at Datamex College Fairview',
            developer: 'AI (Artificial Intelligence)'
        };

        document.title = MINDSPACE_INFO.name + ' v' + MINDSPACE_INFO.version;

        function formatBytes(n) {
            if (n < 1024) return n + ' bytes';
            if (n < 1024 * 1024) return (n / 1024).toFixed(2) + ' KB';
            return (n / (1024 * 1024)).toFixed(2) + ' MB';
        }
        function getSavedDataBytes() {
            // tantya ng laman ng browser storage (UTF-16 = 2 bytes bawat character)
            let chars = 0;
            try {
                for (let i = 0; i < localStorage.length; i++) {
                    const k = localStorage.key(i);
                    chars += k.length + (localStorage.getItem(k) || '').length;
                }
            } catch (e) { }
            return chars * 2;
        }
        function getInfoHeaderComment(codeText) {
            const mk = (size) => '<!--\n' +
                '  ==============================================================\n' +
                '   ' + MINDSPACE_INFO.name + ' version ' + MINDSPACE_INFO.version + '\n' +
                '  ==============================================================\n' +
                '   Memory Used        : ' + formatBytes(size) + ' (' + size.toLocaleString() + ' bytes) - size ng code na ito\n' +
                '   Saved Data         : ' + formatBytes(getSavedDataBytes()) + ' - laman ng browser storage (hindi kasama sa code)\n' +
                '   Creative by        : ' + MINDSPACE_INFO.creator + '\n' +
                '   Background         : ' + MINDSPACE_INFO.background + '\n' +
                '   Developer code by  : ' + MINDSPACE_INFO.developer + '\n' +
                '  ==============================================================\n' +
                '-->\n';
            // dalawang pass para tama ang size kasama na mismong header
            let header = mk(0);
            let size = new Blob([header + codeText]).size;
            header = mk(size);
            size = new Blob([header + codeText]).size;
            return mk(size);
        }

        // isara ang lahat ng ibang pop up (para walang naiiwan sa likod)
        function closeOtherPopups(keepId) {
            document.querySelectorAll('.modal-overlay.active').forEach(m => {
                const id = m.id || '';
                if (id === keepId || id === 'customDialogModal') return;
                try {
                    if (id === 'journalStoryModal') closeJournalStory(true);
                    else if (id === 'stickyPreviewModal') closeStickyPreview(false);
                    else if (id === 'answerModal') closeAnswerModal();
                    else if (id === 'fullCodeModal') closeFullCodeViewer();
                    else if (id === 'profilePreviewModal') closeProfilePreview();
                    else if (id === 'themeColorModal') closeThemeColorPrompt();
                    else if (id === 'autoTypeModal') closeAutoType();
                    else if (id === 'pickerModal') closePicker();
                    else if (id === 'creditsModal') closeCreditsInfo();
                    else if (id === 'aboutMindSpaceModal') closeAboutMindSpace();
                    else if (id === 'mediaMenuModal') closeMediaMenu();
                    else if (id === 'developerModeModal') closeDeveloperConsole();
                    else if (id === 'breakModal' && window.closeBreakTime) window.closeBreakTime();
                    else if (id.indexOf('formPopup_') === 0 && window.closeFormPopup) window.closeFormPopup(id.slice(10));
                    else m.classList.remove('active');
                } catch (e) { m.classList.remove('active'); }
            });
        }

        // When a modal loses .active in Off mode, keep its overlay mounted long enough
        // for the card to fade first and the black tint/blur to fade second.
        (function installSharedModalExitSequence() {
            const exitTimers = new WeakMap();
            const observer = new MutationObserver(records => {
                records.forEach(record => {
                    const modal = record.target;
                    if (!modal.matches || !modal.matches('.modal-overlay')) return;
                    const wasActive = (record.oldValue || '').split(/\s+/).includes('active');
                    if (modal.dataset.skipSharedExit === '1') { delete modal.dataset.skipSharedExit; return; }
                    if (modal.classList.contains('active')) {
                        const pending = exitTimers.get(modal);
                        if (pending) clearTimeout(pending);
                        exitTimers.delete(modal);
                        if (modal.classList.contains('closing')) modal.classList.remove('closing');
                        return;
                    }
                    if (!wasActive) return;
                    if (performanceMode !== 'off') {
                        modal.classList.remove('closing');
                        if (modal.id === 'autoTypeModal') modal.style.removeProperty('--auto-type-close-width');
                        return;
                    }
                    modal.classList.add('closing');
                    const pending = exitTimers.get(modal);
                    if (pending) clearTimeout(pending);
                    const timer = setTimeout(() => {
                        if (!modal.classList.contains('active')) {
                            modal.classList.remove('closing');
                            if (modal.id === 'autoTypeModal') modal.style.removeProperty('--auto-type-close-width');
                        }
                        exitTimers.delete(modal);
                    }, 760);
                    exitTimers.set(modal, timer);
                });
            });
            observer.observe(document.body, { attributes:true, attributeFilter:['class'], attributeOldValue:true, subtree:true });
        })();

        /* ===== Activity Log: detailed local history + one-year Trash Bin ===== */
        const ACTIVITY_LOG_KEY = 'mindspaceActivityLog';
        const ACTIVITY_TRASH_KEY = 'mindspaceActivityTrash';
        const ACTIVITY_LOG_LIMIT = 200;
        const ACTIVITY_TRASH_RETENTION_MS = 365 * 24 * 60 * 60 * 1000;
        let activityLog = [], activityTrash = [];
        try {
            const storedActivity = JSON.parse(localStorage.getItem(ACTIVITY_LOG_KEY) || '[]');
            const storedTrash = JSON.parse(localStorage.getItem(ACTIVITY_TRASH_KEY) || '[]');
            activityLog = Array.isArray(storedActivity) ? storedActivity : [];
            activityTrash = Array.isArray(storedTrash) ? storedTrash : [];
        } catch (_) { activityLog = []; activityTrash = []; }
        function saveActivityLog() { try { localStorage.setItem(ACTIVITY_LOG_KEY, JSON.stringify(activityLog.slice(0, ACTIVITY_LOG_LIMIT))); } catch (_) {} }
        function saveActivityTrash() { try { localStorage.setItem(ACTIVITY_TRASH_KEY, JSON.stringify(activityTrash)); } catch (_) {} }
        function purgeExpiredActivityTrash() {
            const cutoff = Date.now() - ACTIVITY_TRASH_RETENTION_MS;
            const before = activityTrash.length;
            activityTrash = activityTrash.filter(item => Number(item.trashedAt || item.timestamp || 0) > cutoff);
            if (activityTrash.length !== before) saveActivityTrash();
        }
        purgeExpiredActivityTrash();
        function logActivity(message, category='system', icon='fa-circle-info') {
            if (!message) return;
            activityLog.unshift({ id:'activity_' + Date.now() + '_' + Math.random().toString(36).slice(2,7), message:String(message), category, icon, timestamp:Date.now() });
            if (activityLog.length > ACTIVITY_LOG_LIMIT) activityLog.length = ACTIVITY_LOG_LIMIT;
            saveActivityLog();
        }
        function activityDateLabel(timestamp) {
            const d = new Date(timestamp), today = new Date(), yesterday = new Date();
            yesterday.setDate(today.getDate() - 1);
            if (d.toDateString() === today.toDateString()) return 'Today';
            if (d.toDateString() === yesterday.toDateString()) return 'Yesterday';
            return d.toLocaleDateString(undefined, {year:'numeric', month:'long', day:'numeric'});
        }
        function activityEntryHtml(item, trashed=false) {
            const time = new Date(item.timestamp || item.trashedAt || Date.now()).toLocaleTimeString([], {hour:'numeric', minute:'2-digit'});
            const detail = item.details ? `<div class="activity-log-time">${escapeHtml(item.details)}</div>` : '';
            return `<div class="activity-log-item${trashed ? ' activity-trash-item' : ''}"><div class="activity-log-icon"><i class="fa-solid ${escapeHtml(item.icon || 'fa-circle-info')}"></i></div><div><div class="activity-log-message">${escapeHtml(item.message || 'Activity')}</div><div class="activity-log-time">${escapeHtml(activityDateLabel(item.timestamp || item.trashedAt || Date.now()))} · ${escapeHtml(time)}</div>${detail}</div></div>`;
        }
        function renderActivityLog() {
            const list = document.getElementById('activityLogList'); if (!list) return;
            const filter = document.getElementById('activityLogFilter')?.value || 'all';
            const entries = activityLog.filter(item => filter === 'all' || item.category === filter);
            if (!entries.length) { list.innerHTML = '<div class="activity-log-empty"><i class="fa-solid fa-clock-rotate-left"></i><br><br>No activities recorded yet.</div>'; return; }
            let lastDay = '';
            list.innerHTML = entries.map(item => { const day = activityDateLabel(item.timestamp); const heading = day !== lastDay ? `<div class="activity-log-day">${escapeHtml(day)}</div>` : ''; lastDay = day; return heading + activityEntryHtml(item); }).join('');
        }
        function renderActivityTrash() {
            purgeExpiredActivityTrash();
            const list = document.getElementById('activityTrashList'); if (!list) return;
            if (!activityTrash.length) { list.innerHTML = '<div class="activity-log-empty"><i class="fa-solid fa-trash-can"></i><br><br>Trash Bin is empty.</div>'; return; }
            list.innerHTML = activityTrash.slice().sort((a,b) => (b.trashedAt || 0) - (a.trashedAt || 0)).map(item => activityEntryHtml(item, true)).join('');
        }
        function openActivityLog() { closeMediaMenu(); const modal = document.getElementById('activityLogModal'); if (!modal) return; closeOtherPopups('activityLogModal'); renderActivityLog(); modal.classList.add('active'); }
        function closeActivityLog() { const modal = document.getElementById('activityLogModal'); if (modal) modal.classList.remove('active'); }
        function openActivityTrash() { closeActivityLog(); const modal = document.getElementById('activityTrashModal'); if (!modal) return; closeOtherPopups('activityTrashModal'); renderActivityTrash(); modal.classList.add('active'); }
        function closeActivityTrash() { const modal = document.getElementById('activityTrashModal'); if (modal) modal.classList.remove('active'); }
        async function moveActivityLogToTrash() {
            if (!activityLog.length) {
                showCustomAlert('There are no active activity records to move. Create or perform an action first.', 'Trash Bin');
                return false;
            }
            const confirmed = await showCustomConfirm('Move all current activity records to the Trash Bin? They will remain there for 1 year before permanent deletion.', 'Move to Trash Bin', { okLabel: 'Move to Trash', cancelLabel: 'Cancel' });
            if (!confirmed) return false;
            const now = Date.now();
            activityTrash = activityTrash.concat(activityLog.map(item => ({...item, trashedAt:now})));
            activityLog = [];
            saveActivityLog(); saveActivityTrash();
            renderActivityLog(); renderActivityTrash();
            showCustomAlert('Current activity records were moved to the Trash Bin. They will be permanently deleted after 1 year.', 'Moved to Trash Bin');
            return true;
        }
        function exportActivityLog() {
            if (!activityLog.length) { showCustomAlert('There are no active activities to export yet.', 'Activity Log'); return; }
            const payload = { app:'MindSpace', exportedAt:new Date().toISOString(), retention:'Trash Bin records are automatically deleted after one year.', activities:activityLog };
            downloadBlob(new Blob([JSON.stringify(payload, null, 2)], {type:'application/json'}), `MindSpace_Activity_Log_${new Date().toISOString().slice(0,10)}.json`);
        }

        function openMediaMenu() {
            const modal = document.getElementById('mediaMenuModal');
            if (!modal) return;
            closeOtherPopups('mediaMenuModal');
            updateMediaControls();   // para tama kung may Remove button o wala
            updatePerformanceModePrompt();
            syncDeveloperModeUI();
            modal.classList.add('active');
        }

        function updatePerformanceModePrompt() {
            const names = { off: 'Off', reduced: 'Reduced', maximum: 'Maximum' };
            const status = document.getElementById('performanceModeStatus');
            if (status) status.textContent = names[performanceMode] || 'Off';
            const ids = { off: 'performanceOptionOff', reduced: 'performanceOptionReduced', maximum: 'performanceOptionMaximum' };
            Object.keys(ids).forEach(mode => {
                const card = document.getElementById(ids[mode]);
                if (!card) return;
                const selected = mode === performanceMode;
                card.classList.toggle('selected', selected);
                card.setAttribute('aria-pressed', selected ? 'true' : 'false');
            });
        }

        let mobileLagMonitorStarted = false;
        let mobileLagTipShown = false;
        let mobileLagTipPending = false;
        let mobileLagFrameLastAt = 0;
        let mobileLagFrames = [];
        let mobileLagSevereFrames = [];
        let mobileLagLongTasks = [];
        let mobileLagLastCheckAt = 0;

        function mobileLagTipWasSeen() {
            try { return sessionStorage.getItem('mindspaceLagPerformanceTipSeen') === '1'; }
            catch (e) { return mobileLagTipShown; }
        }

        function showLagPerformanceRecommendation() {
            if (mobileLagTipShown || mobileLagTipWasSeen() || performanceMode === 'maximum') return;
            const modal = document.getElementById('lagPerformanceModal');
            if (!modal) return;
            const loading = document.getElementById('loading-screen');
            if (document.hidden || (loading && !loading.classList.contains('hidden'))) return;
            // Huwag patungan ang ibang dialog, theme preview, o tutorial card.
            if (document.querySelector('.modal-overlay.active, .theme-change-overlay, #tutCard.show')) return;

            mobileLagTipPending = false;
            mobileLagTipShown = true;
            try { sessionStorage.setItem('mindspaceLagPerformanceTipSeen', '1'); } catch (e) {}
            const copy = document.getElementById('lagPerformanceCopy');
            if (copy && performanceMode === 'reduced') {
                copy.textContent = 'Reduced Effects is already on. If the app still feels slow, choose Maximum Performance to also remove decorative shadows and glows.';
            }
            modal.classList.add('active');
        }

        function dismissLagPerformanceRecommendation() {
            const modal = document.getElementById('lagPerformanceModal');
            if (modal) modal.classList.remove('active');
            if (developerLagPreviewActive) {
                developerLagPreviewActive = false;
                const title = document.getElementById('lagPerformanceTitle');
                const copy = document.getElementById('lagPerformanceCopy');
                if (developerLagPreviewOriginal && title && copy) {
                    title.textContent = developerLagPreviewOriginal.title;
                    copy.textContent = developerLagPreviewOriginal.copy;
                }
                developerLagPreviewOriginal = null;
                if (developerModeEnabled && !developerReturnAfterPerformance) window.setTimeout(openDeveloperConsole, 90);
            }
        }
        function openPerformanceModeFromLag() {
            developerReturnAfterPerformance = developerLagPreviewActive;
            dismissLagPerformanceRecommendation();
            window.setTimeout(openPerformanceModePrompt, 80);
        }
        function mobileLagFrameLoop(now) {
            if (!mobileLagMonitorStarted) return;
            if (document.hidden) {
                mobileLagFrameLastAt = 0;
                requestAnimationFrame(mobileLagFrameLoop);
                return;
            }
            if (mobileLagFrameLastAt) {
                const delta = now - mobileLagFrameLastAt;
                if (delta > 0 && delta < 1200) {
                    mobileLagFrames.push({ at: now, slow: delta >= 50 });
                    if (delta >= 220) mobileLagSevereFrames.push(now);
                }
            }
            mobileLagFrameLastAt = now;
            const tenSecondsAgo = now - 10000;
            mobileLagFrames = mobileLagFrames.filter(sample => sample.at >= tenSecondsAgo);
            mobileLagSevereFrames = mobileLagSevereFrames.filter(at => at >= now - 20000);
            mobileLagLongTasks = mobileLagLongTasks.filter(at => at >= now - 30000);

            if (now - mobileLagLastCheckAt >= 5000) {
                mobileLagLastCheckAt = now;
                const frameCount = mobileLagFrames.length;
                const slowCount = mobileLagFrames.reduce((count, sample) => count + (sample.slow ? 1 : 0), 0);
                const sustainedSlowRendering = frameCount >= 50 && slowCount >= 10 && slowCount / frameCount >= 0.2;
                const repeatedFreezes = mobileLagSevereFrames.length >= 3 || mobileLagLongTasks.length >= 2;
                if (sustainedSlowRendering || repeatedFreezes) mobileLagTipPending = true;
                if (mobileLagTipPending) showLagPerformanceRecommendation();
            }
            requestAnimationFrame(mobileLagFrameLoop);
        }

        function startMobileLagMonitor() {
            if (mobileLagMonitorStarted || !isPhoneDevice() || mobileLagTipWasSeen()) return;
            if (performanceMode === 'maximum') return;
            mobileLagMonitorStarted = true;
            mobileLagFrameLastAt = 0;
            mobileLagLastCheckAt = performance.now();
            try {
                if ('PerformanceObserver' in window && PerformanceObserver.supportedEntryTypes?.includes('longtask')) {
                    const observer = new PerformanceObserver(list => {
                        const now = performance.now();
                        list.getEntries().forEach(entry => {
                            if (entry.duration >= 220) mobileLagLongTasks.push(now);
                        });
                    });
                    observer.observe({ type: 'longtask', buffered: false });
                }
            } catch (e) { /* RAF sampling remains available on browsers without long-task support. */ }
            document.addEventListener('visibilitychange', () => { if (!document.hidden) mobileLagFrameLastAt = 0; });
            requestAnimationFrame(mobileLagFrameLoop);
        }

        function openPerformanceModePrompt() {
            const modal = document.getElementById('performanceModeModal');
            if (!modal) return;
            closeOtherPopups('performanceModeModal');
            updatePerformanceModePrompt();
            modal.classList.add('active');
        }

        function closePerformanceModePrompt() {
            const modal = document.getElementById('performanceModeModal');
            if (modal) modal.classList.remove('active');
            if (developerReturnAfterPerformance) {
                developerReturnAfterPerformance = false;
                window.setTimeout(openDeveloperConsole, 90);
            }
        }

        function choosePerformanceMode(mode) {
            if (!['off', 'reduced', 'maximum'].includes(mode)) return;
            setPerformanceMode(mode);
            closePerformanceModePrompt();
        }

        function setPerformanceMode(mode) {
            if (!['off', 'reduced', 'maximum'].includes(mode)) return;
            themeOptionsWarm = false;
            performanceMode = mode;
            try { localStorage.setItem('appPerformanceMode', mode); localStorage.removeItem('appBatterySaver'); } catch (e) {}
            const root = document.documentElement;
            if (mode === 'off') root.removeAttribute('data-performance-mode');
            else root.setAttribute('data-performance-mode', mode);
            applyThemeColor(currentThemeColorKey, false);
            updatePerformanceModePrompt();
            updateStatusBarColor();
            if (document.getElementById('themeColorModal')?.classList.contains('active')) openThemeColorPrompt();
        }
        function closeMediaMenu() {
            const modal = document.getElementById('mediaMenuModal');
            if (modal) modal.classList.remove('active');
        }
        // ===== Developer Mode: local, read-only runtime diagnostics =====
        let developerModeEnabled = false;
        let developerDiagErrors = [];
        let developerFpsFrameAt = 0;
        let developerFpsCount = 0;
        let developerFpsLastAt = 0;
        let developerFpsLoopRunning = false;
        let developerLagPreviewActive = false;
        let developerLagPreviewOriginal = null;
        let developerReturnAfterPerformance = false;
        try { developerModeEnabled = localStorage.getItem('mindspaceDeveloperMode') === '1'; } catch (_) {}
        window.addEventListener('error', event => {
            const message = (event && (event.message || event.error?.message)) || 'Unknown JavaScript error';
            developerDiagErrors.push({ message: String(message).slice(0, 240), at: new Date().toLocaleTimeString() });
            if (developerDiagErrors.length > 20) developerDiagErrors.shift();
            if (developerModeEnabled) refreshDeveloperErrorSummary();
        });
        window.addEventListener('unhandledrejection', event => {
            const reason = event && event.reason;
            const message = reason && reason.message ? reason.message : String(reason || 'Unhandled promise rejection');
            developerDiagErrors.push({ message: String(message).slice(0, 240), at: new Date().toLocaleTimeString() });
            if (developerDiagErrors.length > 20) developerDiagErrors.shift();
            if (developerModeEnabled) refreshDeveloperErrorSummary();
        });
        function syncDeveloperModeUI() {
            const status = document.getElementById('developerModeStatus');
            const button = document.getElementById('developerModeMenuButton');
            if (status) status.textContent = developerModeEnabled ? 'On' : 'Off';
            if (button) button.setAttribute('aria-pressed', developerModeEnabled ? 'true' : 'false');
        }
        function toggleDeveloperMode() { setDeveloperMode(!developerModeEnabled); }
        function setDeveloperMode(enabled) {
            developerModeEnabled = !!enabled;
            try { localStorage.setItem('mindspaceDeveloperMode', developerModeEnabled ? '1' : '0'); } catch (_) {}
            syncDeveloperModeUI();
            closeMediaMenu();
            if (developerModeEnabled) openDeveloperConsole();
            else {
                closeDeveloperConsole();
                if (developerLagPreviewActive) dismissLagPerformanceRecommendation();
            }
        }
        function openDeveloperConsole() {
            if (!developerModeEnabled) return;
            const modal = document.getElementById('developerModeModal');
            if (!modal) return;
            closeOtherPopups('developerModeModal');
            modal.classList.add('active');
            const version = document.getElementById('developerVersionLabel');
            if (version) version.textContent = 'v' + MINDSPACE_INFO.version;
            refreshDeveloperDiagnostics();
            startDeveloperFpsSampler();
        }
        function closeDeveloperConsole() {
            const modal = document.getElementById('developerModeModal');
            if (modal) modal.classList.remove('active');
        }
        function startDeveloperFpsSampler() {
            if (developerFpsLoopRunning) return;
            developerFpsLoopRunning = true;
            developerFpsFrameAt = 0;
            developerFpsCount = 0;
            developerFpsLastAt = performance.now();
            const tick = now => {
                const modal = document.getElementById('developerModeModal');
                if (!developerModeEnabled || !modal || !modal.classList.contains('active')) {
                    developerFpsLoopRunning = false;
                    return;
                }
                if (developerFpsFrameAt) developerFpsCount++;
                developerFpsFrameAt = now;
                if (now - developerFpsLastAt >= 1000) {
                    const fps = Math.round(developerFpsCount * 1000 / (now - developerFpsLastAt));
                    const value = document.getElementById('devFpsValue');
                    const status = document.getElementById('devRenderStatus');
                    if (value) value.textContent = fps + ' FPS';
                    if (status) status.textContent = fps >= 50 ? 'Smooth rendering' : fps >= 30 ? 'Some dropped frames' : 'Low frame rate';
                    developerFpsCount = 0;
                    developerFpsLastAt = now;
                }
                requestAnimationFrame(tick);
            };
            requestAnimationFrame(tick);
        }
        function refreshDeveloperErrorSummary() {
            const count = document.getElementById('devErrorCount');
            const latest = document.getElementById('devLatestError');
            if (count) count.textContent = String(developerDiagErrors.length);
            if (latest) {
                const item = developerDiagErrors[developerDiagErrors.length - 1];
                latest.textContent = item ? `${item.at} — ${item.message}` : 'No runtime errors captured in this session.';
            }
        }
        function refreshDeveloperDiagnostics() {
            if (!developerModeEnabled) return;
            const setText = (id, value) => { const el = document.getElementById(id); if (el) el.textContent = value; };
            setText('devNetworkValue', navigator.onLine ? 'Online' : 'Offline');
            const connection = navigator.connection || navigator.mozConnection || navigator.webkitConnection;
            setText('devNetworkType', connection ? [connection.effectiveType, connection.downlink ? connection.downlink + ' Mbps' : ''].filter(Boolean).join(' · ') || 'Connection info available' : 'Connection details unavailable');
            setText('devPerformanceValue', ({off:'Off', reduced:'Reduced', maximum:'Maximum'})[performanceMode] || 'Unknown');
            setText('devViewportValue', `Viewport: ${window.innerWidth} × ${window.innerHeight}`);
            setText('devPlatformValue', (navigator.userAgentData && navigator.userAgentData.platform) || navigator.platform || 'Not reported');
            setText('devCpuValue', navigator.hardwareConcurrency ? `${navigator.hardwareConcurrency} logical cores` : 'Not reported');
            setText('devMemoryValue', navigator.deviceMemory ? `About ${navigator.deviceMemory} GB` : 'Not reported');
            const loadTime = performance.getEntriesByType && performance.getEntriesByType('navigation')[0];
            setText('devPageLoadValue', loadTime && loadTime.loadEventEnd ? `${(loadTime.loadEventEnd / 1000).toFixed(2)} s` : 'Available after load');
            setText('devDomValue', `${document.getElementsByTagName('*').length.toLocaleString()} elements`);
            setText('devImagesValue', `${document.images.length.toLocaleString()} images`);
            const storedBytes = typeof getSavedDataBytes === 'function' ? getSavedDataBytes() : 0;
            setText('devStorageValue', formatBytes(storedBytes) + ' used');
            setText('devStorageDetail', 'App data estimate in local storage');
            if (navigator.storage && navigator.storage.estimate) {
                navigator.storage.estimate().then(info => {
                    if (!developerModeEnabled) return;
                    const quota = Number(info.quota) || 0, usage = Number(info.usage) || 0;
                    if (quota) {
                        setText('devStorageValue', formatBytes(usage) + ' used');
                        setText('devStorageDetail', `${formatBytes(quota)} estimated quota · browser estimate`);
                    }
                }).catch(() => {});
            }
            if (performance.memory && performance.memory.usedJSHeapSize) {
                setText('devMemoryValue', `${navigator.deviceMemory ? 'Device ' + navigator.deviceMemory + ' GB · ' : ''}${formatBytes(performance.memory.usedJSHeapSize)} JS heap`);
            }
            refreshDeveloperErrorSummary();
        }
        function showDeveloperLagPreview() {
            if (!developerModeEnabled) return;
            const modal = document.getElementById('lagPerformanceModal');
            const title = document.getElementById('lagPerformanceTitle');
            const copy = document.getElementById('lagPerformanceCopy');
            if (!modal || !title || !copy) return;
            developerLagPreviewOriginal = { title:title.textContent, copy:copy.textContent };
            developerLagPreviewActive = true;
            title.textContent = 'Developer preview: Lag detected';
            copy.textContent = 'This is a preview only. It shows the lag recommendation card so you can test its appearance and buttons; it does not indicate an actual performance issue.';
            closeDeveloperConsole();
            modal.classList.add('active');
        }
        function buildDeveloperReport() {
            const connection = navigator.connection || navigator.mozConnection || navigator.webkitConnection;
            const errors = developerDiagErrors.length ? developerDiagErrors.map(item => `- ${item.at}: ${item.message}`).join('\n') : 'None captured in this session';
            return [
                `MindSpace Developer Diagnostics — v${MINDSPACE_INFO.version}`,
                `Generated: ${new Date().toLocaleString()}`,
                `Network: ${navigator.onLine ? 'Online' : 'Offline'}${connection?.effectiveType ? ' (' + connection.effectiveType + ')' : ''}`,
                `Performance mode: ${({off:'Off',reduced:'Reduced',maximum:'Maximum'})[performanceMode] || 'Unknown'}`,
                `Viewport: ${window.innerWidth} × ${window.innerHeight}`,
                `Platform: ${(navigator.userAgentData && navigator.userAgentData.platform) || navigator.platform || 'Not reported'}`,
                `CPU cores: ${navigator.hardwareConcurrency || 'Not reported'}`,
                `Device memory: ${navigator.deviceMemory ? navigator.deviceMemory + ' GB' : 'Not reported'}`,
                `DOM elements: ${document.getElementsByTagName('*').length}`,
                `Images: ${document.images.length}`,
                `Local storage estimate: ${formatBytes(typeof getSavedDataBytes === 'function' ? getSavedDataBytes() : 0)}`,
                `Runtime errors captured: ${developerDiagErrors.length}`,
                errors,
                'Note: Estimates are browser-reported; report contains no journal content.'
            ].join('\n');
        }
        async function copyDeveloperReport() {
            const report = buildDeveloperReport();
            try {
                await navigator.clipboard.writeText(report);
                showCustomAlert('Developer diagnostic summary copied. It does not include journal text or photos.', 'Report Copied');
            } catch (_) {
                showCustomAlert(report, 'Developer Diagnostic Report');
            }
        }
        syncDeveloperModeUI();
        // isasara muna ang Menu, tsaka gagawin ang napiling action
        function menuAction(fn) {
            closeMediaMenu();
            try { fn(); } catch (e) { console.error(e); }
        }



        const CREDITS_REFRESH_MS = 4000;   // 4 seconds ang refresh ng Memory Used sa Credits & Information
        let creditsRefreshTimer = null;
        function refreshCreditsSizes() {
            const codeEl = document.getElementById('creditsCodeSize');
            const dataEl = document.getElementById('creditsDataSize');
            if (!codeEl || !dataEl) return;
            const source = '<!DOCTYPE html>\n' + document.documentElement.outerHTML;
            codeEl.textContent = formatBytes(new Blob([source]).size) + ' (code size)';
            dataEl.textContent = 'Saved data in browser: ' + formatBytes(getSavedDataBytes());
        }

        function openCreditsInfo() {
            const modal = document.getElementById('creditsModal');
            if (!modal) return;
            closeOtherPopups('creditsModal');
            document.getElementById('creditsVersion').textContent = 'Version ' + MINDSPACE_INFO.version;
            refreshCreditsSizes();
            clearInterval(creditsRefreshTimer);
            creditsRefreshTimer = setInterval(refreshCreditsSizes, CREDITS_REFRESH_MS);   // auto-refresh habang bukas
            document.getElementById('creditsCreator').textContent = MINDSPACE_INFO.creator;
            document.getElementById('creditsBackground').textContent = MINDSPACE_INFO.background;
            document.getElementById('creditsDeveloper').textContent = MINDSPACE_INFO.developer;
            modal.classList.add('active');
        }
        function closeCreditsInfo() {
            clearInterval(creditsRefreshTimer); creditsRefreshTimer = null;
            const modal = document.getElementById('creditsModal');
            if (modal) modal.classList.remove('active');
        }
        function openAboutMindSpace() {
            const modal = document.getElementById('aboutMindSpaceModal');
            if (!modal) return;
            closeOtherPopups('aboutMindSpaceModal');
            modal.classList.add('active');
        }
        function closeAboutMindSpace() {
            const modal = document.getElementById('aboutMindSpaceModal');
            if (modal) modal.classList.remove('active');
        }
        function returnToCreditsFromAbout() {
            closeAboutMindSpace();
            openCreditsInfo();
        }
        // kapag may ibang pop up na bumukas habang bukas ang Credits, kusang magsasara ang Credits
        (function () {
            const watch = new MutationObserver(muts => {
                const credits = document.getElementById('creditsModal');
                if (!credits || !credits.classList.contains('active')) return;
                for (const m of muts) {
                    const t = m.target;
                    if (t !== credits && t.classList && t.classList.contains('modal-overlay') &&
                        t.classList.contains('active') && t.id !== 'customDialogModal') {
                        closeCreditsInfo();
                        return;
                    }
                }
            });
            watch.observe(document.body, { attributes: true, attributeFilter: ['class'], subtree: true });
        })();
        function adjustPreviewFontSize(delta) {
            currentFontSize += delta;
            if (currentFontSize < 11) currentFontSize = 11;
            if (currentFontSize > 26) currentFontSize = 26;
            applyFontSize(currentFontSize);
        }

        function applyFontSize(size) {
            currentFontSize = size;
            localStorage.setItem('previewFontSize', size);
            document.documentElement.style.setProperty('--preview-font-size', `${size}px`);
        }

        function adjustModalFontSize(delta) {
            currentModalFontSize += delta;
            if (currentModalFontSize < 10) currentModalFontSize = 10;
            if (currentModalFontSize > 28) currentModalFontSize = 28;
            applyModalFontSize(currentModalFontSize);
        }

        function applyModalFontSize(size) {
            currentModalFontSize = size;
            localStorage.setItem('modalFontSize', size);
            document.documentElement.style.setProperty('--modal-font-size', `${size}px`);
        }

        function setMindSpaceLoadingProgress(progress, label) {
            const bar = document.getElementById('ytLoaderBar');
            const status = document.getElementById('loadingProgressLabel');
            const value = Math.max(0, Math.min(100, Number(progress) || 0));
            if (bar) {
                bar.style.width = value + '%';
                bar.setAttribute('role', 'progressbar');
                bar.setAttribute('aria-valuemin', '0');
                bar.setAttribute('aria-valuemax', '100');
                bar.setAttribute('aria-valuenow', String(value));
            }
            if (status && label) status.textContent = label;
        }

        function waitForMindSpacePaint() {
            return new Promise(resolve => {
                if (typeof window.requestAnimationFrame === 'function') {
                    window.requestAnimationFrame(() => window.requestAnimationFrame(resolve));
                } else {
                    setTimeout(resolve, 32);
                }
            });
        }

        async function preloadMindSpaceStoredImages() {
            const images = Array.from(document.querySelectorAll('.app-card-wrapper img[src^="data:image/"]'));
            if (!images.length) {
                setMindSpaceLoadingProgress(99, 'No saved photos to prepare.');
                return;
            }
            let ready = 0;
            for (let start = 0; start < images.length; start += 4) {
                const batch = images.slice(start, start + 4);
                await Promise.all(batch.map(async image => {
                    image.loading = 'eager';
                    try {
                        if (typeof image.decode === 'function') await image.decode();
                        else if (!image.complete) await new Promise(resolve => {
                            image.addEventListener('load', resolve, { once: true });
                            image.addEventListener('error', resolve, { once: true });
                            if (image.complete) resolve();
                        });
                    } catch (_) {}
                }));
                ready += batch.length;
                setMindSpaceLoadingProgress(95 + Math.round(4 * ready / images.length), `Preparing saved photos (${ready}/${images.length})...`);
                if (start % 16 === 0) await waitForMindSpacePaint();
            }
        }

        function startYouTubeLoader() {
            const quoteEl = document.getElementById('motivationQuote');
            const dailyQuote = mindspaceAutoPosts[0] && mindspaceAutoPosts[0].content;
            const randomQuote = dailyQuote ? `"${dailyQuote}"` : motivationalQuotes[Math.floor(Math.random() * motivationalQuotes.length)];
            quoteEl.textContent = randomQuote;
            if (IS_FIRST_TIME) {
                const sub = document.querySelector('#loading-screen .loading-subtext');
                if (sub) sub.textContent = 'Welcome to MindSpace';
                quoteEl.textContent = '"Set your name and year & section to get started."';
            }
            setMindSpaceLoadingProgress(4, 'Checking saved data and preparing MindSpace...');
        }


        /* ===== v1.77: FIRST-TIME TUTORIAL =====
           Guided steps: user must actually try each feature. Auto-detects completion.
           Progress is saved (mindspaceTutorial) so a refresh won't lose it. */
        /* v1.79: bawat step ay may "subs" = sunod-sunod na tinuturo (highlight). Kusang lilipat sa susunod
           kapag nagawa na ng user ang kasalukuyan. Ang huling sub ang tatapos sa step (auto-detect na dati). */
        const tutPaneOn = id => () => { const el = document.getElementById(id); return !!el && getComputedStyle(el).display !== 'none'; };
        const tutFilled = id => () => { const el = document.getElementById(id); return !!el && el.value.trim().length > 0 && document.activeElement !== el; };
        const tutPopupOn = k => () => { const el = document.getElementById('formPopup_' + k); return !!el && el.classList.contains('active'); };
        const tutChanged = {};   // id -> oras ng huling 'change' event (hal. pumili sa picker)
        let tutSubIdx = 0, tutSubStart = 0, tutStepStart = 0;
        const tutPicked = id => () => (tutChanged[id] || 0) > tutStepStart;
        const tutLast = () => false;
        const TUT_STEPS = [
            { id:'profile', title:'Set up your profile', text:'Tap the pencil icons beside Name and Year & Section, then type your own details.',
              go: function(){ window.scrollTo({top:0,behavior:'smooth'}); }, hl:'.profile-details .info-row .edit-info-btn', zone:'.profile-details',
              check: function(){ return !!localStorage.getItem('profileName') && !!localStorage.getItem('profileSection'); },
              subs: [
                { sel:'.profile-details .info-row .edit-info-btn',  done:()=>!!localStorage.getItem('profileName'),    hint:'Tap the pencil beside Name, then type your name and press OK.' },
                { sel:'.profile-details .info-row2 .edit-info-btn', done:tutLast,                                      hint:'Now tap the pencil beside Year & Section and type it in.' } ] },
            { id:'test', title:'Try the Tester / Reviewer', text:'Pick a question, type your answer in the notepad, then press "Check Answer". Try the sample question!',
              go: function(){ switchTab('test'); }, hl:'#tabTestBtn', zone:'#testSection',
              subs: [
                { sel:'#tabTestBtn',                 hold:1200, done:tutPaneOn('testSection'), hint:'This is the Tester / Reviewer tab.' },
                { sel:'#practiceFilterSubjectBtn',   done:tutPicked('practiceFilterSubject'), hint:'Tap "Filter Question by Subject" and choose a subject.' },
                { sel:'#questionSelectDropdownBtn',  done:tutPicked('questionSelectDropdown'), hint:'Next, tap "Select Question to Practice" and choose a question.' },
                { sel:'#notepadInput',               done:tutFilled('notepadInput'), hint:'Type your answer in the notepad. Anything works for now.' },
                { sel:'#testSection .btn-check',     done:tutLast, hint:'Press "Check Answer & Highlight Mismatches" to see your score.' } ] },
            { id:'add', title:'Add your own question', text:'Type a Topic Tag, a Question, and the Answer Key, then press "Save Reviewer Question".',
              go: function(){ switchTab('add'); }, hl:'#tabAddBtn', zone:'#addSection',
              subs: [
                { sel:'#tabAddBtn',          hold:1200, done:tutPaneOn('addSection'), hint:'This is the Add Item tab.' },
                { sel:'#codeTag',            done:tutFilled('codeTag'),  hint:'Type a Tag Title / Topic Name.' },
                { sel:'#codeDesc',           done:tutFilled('codeDesc'), hint:'Write your Question / Prompt here.' },
                { sel:'#codeKey',            done:tutFilled('codeKey'),  hint:'Type the exact Answer Key here.' },
                { sel:'#saveQuestionBtn',    done:tutLast, hint:'Press "Save Reviewer Question".' } ] },
            { id:'journal', title:'Write a journal entry', text:'Add a title and your thoughts, then post it.',
              go: function(){ switchTab('journal'); }, hl:'#tabJournalBtn', zone:'#journalSection',
              subs: [
                { sel:'#tabJournalBtn',        hold:1200, done:tutPaneOn('journalSection'), hint:'This is the Journal / Diary tab.' },
                { sel:'#journalSection .form-trigger', done:tutPopupOn('journal'), hint:'Tap "What\'s on your mind? Create Post / Diary / Journal Thoughts..." to open the post form.' },
                { sel:'#journalTitleInput',    pop:'journal', done:tutFilled('journalTitleInput'),   hint:'Type a title for your entry.' },
                { sel:'#journalContentInput',  pop:'journal', done:tutFilled('journalContentInput'), hint:'Write your thoughts here.' },
                { sel:'#saveJournalBtn',       pop:'journal', done:tutLast, hint:'Press "Post Thought".' } ] },
            { id:'sticky', title:'Make a sticky note', text:'Write a title and a quick note, pick a color if you like, then save it.',
              go: function(){ switchTab('sticky'); }, hl:'#tabStickyBtn', zone:'#stickySection',
              subs: [
                { sel:'#tabStickyBtn',         hold:1200, done:tutPaneOn('stickySection'), hint:'This is the Sticky Notes tab.' },
                { sel:'#stickySection .form-trigger', done:tutPopupOn('sticky'), hint:'Tap "Quick Add Sticky Note Reviewer" to open the form.' },
                { sel:'#stickyTitleInput',     pop:'sticky', done:tutFilled('stickyTitleInput'),   hint:'Type a title for your sticky note.' },
                { sel:'#stickyContentInput',   pop:'sticky', done:tutFilled('stickyContentInput'), hint:'Write your quick note here.' },
                { sel:'#stickyColorSelect',     pop:'sticky', done:tutPicked('stickyColorSelect'), hint:'Pick a color for your sticky note.' },
                { sel:'#saveStickyBtn',          pop:'sticky', done:tutLast, hint:'Now press "+ Add Item" to save your sticky note.' } ] },
            { id:'bible', title:'Add a Bible devotion', text:'Type a verse reference, the scripture, and your reflection, then save it.',
              go: function(){ switchTab('bible'); }, hl:'#tabBibleBtn', zone:'#bibleSection',
              subs: [
                { sel:'#tabBibleBtn',            hold:1200, done:tutPaneOn('bibleSection'), hint:'This is the Bible Devotion tab.' },
                { sel:'#bibleSection .form-trigger', done:tutPopupOn('bible'), hint:'Tap "Add Bible Verse & Devotion Reflection" to open the form.' },
                { sel:'#bibleReferenceInput',    pop:'bible', done:tutFilled('bibleReferenceInput'), hint:'Type the Book, Chapter & Verse (e.g. Philippians 4:13).' },
                { sel:'#bibleScriptureInput',    pop:'bible', done:tutFilled('bibleScriptureInput'), hint:'Type the scripture text.' },
                { sel:'#bibleDevotionInput',     pop:'bible', done:tutFilled('bibleDevotionInput'),  hint:'Write your devotion / reflection.' },
                { sel:'#saveBibleBtn',           pop:'bible', done:tutLast, hint:'Press "+ Post Bible Devotion".' } ] }
        ];
        let tutState = null, tutPoll = null, tutAdvanceTimer = null;

        function tutSave() { try { localStorage.setItem('mindspaceTutorial', JSON.stringify(tutState)); } catch (e) {} }
        function tutClearHl() { document.querySelectorAll('.tut-highlight').forEach(el => el.classList.remove('tut-highlight')); }

        function startTutorial(force) {
            if (force || !tutState) tutState = { step: 0, done: [] };
            tutSave();
            renderTutorial();
        }

        function tutMarkDone(id) {
            if (!tutState || tutState.finished) return;
            const cur = TUT_STEPS[tutState.step];
            if (!cur || cur.id !== id || tutState.done.indexOf(id) !== -1) return;
            tutState.done.push(id);
            tutSave();
            renderTutorial(true);
            clearTimeout(tutAdvanceTimer);
            tutAdvanceTimer = setTimeout(() => tutNext(), 1600);
        }

        function tutNext() {
            if (!tutState) return;
            clearTimeout(tutAdvanceTimer);
            tutState.step++;
            tutSave();
            renderTutorial();
        }

        function renderTutorial(justDone) {
            const card = document.getElementById('tutCard');
            if (!tutState || tutState.closed) { card.classList.remove('show'); tutSetMode('off'); return; }
            tutClearHl();
            const total = TUT_STEPS.length;
            const actions = document.getElementById('tutActions');
            actions.innerHTML = '';
            const mk = (label, cls, fn) => { const b = document.createElement('button'); b.type = 'button'; b.textContent = label; if (cls) b.className = cls; b.onclick = fn; actions.appendChild(b); };
            card.classList.toggle('done-step', !!justDone);
            if (tutState.step >= total) {
                tutState.finished = true; tutSave();
                document.getElementById('tutStepLabel').textContent = 'Tutorial complete';
                document.getElementById('tutBarFill').style.width = '100%';
                document.getElementById('tutTitle').textContent = "You're all set!";
                document.getElementById('tutText').textContent = 'You tried every main feature of MindSpace. You can replay this anytime from Menu > Start Tutorial.';
                mk('Start using MindSpace', 'primary', closeTutorial);
                tutSetMode('done');
                card.classList.add('show');
                return;
            }
            const st = TUT_STEPS[tutState.step];
            document.getElementById('tutStepLabel').textContent = 'Step ' + (tutState.step + 1) + ' of ' + total;
            document.getElementById('tutBarFill').style.width = ((tutState.step + (justDone ? 1 : 0)) / total * 100) + '%';
            if (justDone) {
                document.getElementById('tutTitle').textContent = 'Nice! Step done.';
                document.getElementById('tutText').textContent = 'Moving to the next step...';
                tutSetMode('done');
            } else {
                document.getElementById('tutTitle').textContent = st.title;
                document.getElementById('tutText').textContent = st.text;
                mk('Take me there', 'primary', tutFocus);
                mk('Skip step', '', tutNext);
                tutSubIdx = 0; tutSubStart = tutStepStart = Date.now();
                tutSetMode('intro');   // madilim ang paligid, naka-highlight ang pop up
            }
            card.classList.add('show');
        }

        function closeTutorial() {
            clearTimeout(tutAdvanceTimer);
            if (tutState && !tutState.finished) { tutState.closed = true; tutSave(); }
            tutClearHl();
            tutSetMode('off');
            document.getElementById('tutCard').classList.remove('show');
        }

        /* ===== v1.78: SPOTLIGHT ENGINE =====
           intro   = madilim ang buong paligid, naka-highlight lang ang pop up
           focus   = "Take me there" -> auto-scroll + madilim ang paligid, may butas/highlight ang tinutukoy na button
           relaxed = hindi sinunod ng user -> fade out ang dilim, nandun pa rin ang pop up, naka-highlight ulit ang button
           done/off = walang dilim, walang highlight */
        let tutMode = 'off', tutIdleTimer = null, tutRaf = null, tutStray = 0, tutLastFlip = 0;
        const TUT_IDLE_INTRO = 20000;   // ms: ilang segundo bago ma-"relax" kung walang pinindot sa pop up
        const TUT_IDLE_FOCUS = 15000;   // ms: ilang segundo bago ma-"relax" kung walang ginawa sa tinuturo
        const TUT_STRAY_LIMIT = 2;      // ilang beses mag-click sa ibang lugar bago ma-"relax"

        function tutCurStep() { return (tutState && TUT_STEPS[tutState.step]) || null; }
        function tutCurSel() {
            const st = tutCurStep(); if (!st) return '';
            const sb = st.subs && st.subs[tutSubIdx];
            if (!sb) return st.hl;
            if (sb.pop && !tutPopupOn(sb.pop)()) return st.subs[1].sel;   // sarado ang popup -> ituro ulit yung bar na nagbubukas nito
            return sb.sel;
        }

        function tutTargets(sel) {
            if (!sel) return [];
            return Array.prototype.slice.call(document.querySelectorAll(sel)).filter(function (el) {
                const r = el.getBoundingClientRect(); return r.width > 0 && r.height > 0;
            });
        }

        function tutRect() {
            const st = tutCurStep(); if (!st) return null;
            const els = tutTargets(tutCurSel()); if (!els.length) return null;
            const rs = els.map(function (el) { return el.getBoundingClientRect(); });
            let l = Math.min.apply(null, rs.map(r => r.left)), t = Math.min.apply(null, rs.map(r => r.top));
            let rgt = Math.max.apply(null, rs.map(r => r.right)), b = Math.max.apply(null, rs.map(r => r.bottom));
            if (els.length > 1 && ((b - t) > window.innerHeight * 0.5 || (rgt - l) > window.innerWidth * 0.9)) {
                l = rs[0].left; t = rs[0].top; rgt = rs[0].right; b = rs[0].bottom;   // masyadong magkalayo, unang button lang
            }
            return { l: l, t: t, r: rgt, b: b };
        }

        function tutSetMode(m) {
            tutMode = m;
            const card = document.getElementById('tutCard');
            document.getElementById('tutDim').classList.toggle('on', m === 'intro');
            const spot = document.getElementById('tutSpot');
            spot.classList.toggle('show', m === 'focus' || m === 'relaxed');
            spot.classList.toggle('dim', m === 'focus');
            card.classList.toggle('tut-emph', m === 'intro' || m === 'focus');
            if (m === 'intro' || m === 'off') card.classList.remove('top');
            clearTimeout(tutIdleTimer);
            cancelAnimationFrame(tutRaf);
            if (m === 'intro' || m === 'focus') tutArmIdle();
            if (m === 'focus' || m === 'relaxed') { tutTrackLoop(); tutShowHint(); }
        }

        function tutArmIdle() {
            clearTimeout(tutIdleTimer);
            if (tutMode !== 'intro' && tutMode !== 'focus') return;
            tutIdleTimer = setTimeout(tutRelax, tutMode === 'intro' ? TUT_IDLE_INTRO : TUT_IDLE_FOCUS);
        }

        function tutRelax() {
            if (tutMode === 'intro' || tutMode === 'focus') tutSetMode('relaxed');
        }

        function tutScrollToTarget(force) {
            const el = tutTargets(tutCurSel())[0]; if (!el) return;
            const r = el.getBoundingClientRect();
            const visible = r.top >= 60 && r.bottom <= window.innerHeight - 60;
            if (force || !visible) { try { el.scrollIntoView({ behavior: 'smooth', block: 'center', inline: 'center' }); } catch (e) { el.scrollIntoView(); } }
        }

        function tutFocus() {
            const idx = tutState ? tutState.step : -1;
            const st = tutCurStep(); if (!st) return;
            try { st.go(); } catch (e) {}
            tutStray = 0;
            if (tutMode === 'intro') tutSubStart = Date.now();
            setTimeout(function () {
                if (!tutState || tutState.closed || tutState.finished || tutState.step !== idx) return;
                tutScrollToTarget(true);
            }, 90);
            tutSetMode('focus');
        }

        function tutShowHint() {
            if (tutMode !== 'focus' && tutMode !== 'relaxed') return;
            const st = tutCurStep(); if (!st || !st.subs) return;
            const sb = st.subs[tutSubIdx]; if (!sb) return;
            document.getElementById('tutText').textContent = (sb.pop && !tutPopupOn(sb.pop)()) ? st.subs[1].hint : sb.hint;
            document.getElementById('tutStepLabel').textContent = 'Step ' + (tutState.step + 1) + ' of ' + TUT_STEPS.length + '  \u00b7  ' + (tutSubIdx + 1) + '/' + st.subs.length;
        }

        // Kusang lilipat ang highlight sa susunod na tinuturo kapag nagawa na ng user ang kasalukuyan
        function tutSubTick() {
            if (!tutState || tutState.finished || tutState.closed) return;
            if (tutMode !== 'focus' && tutMode !== 'relaxed') return;
            const st = tutCurStep(); if (!st || !st.subs) return;
            let i = tutSubIdx;
            for (let k = st.subs.length - 2; k >= i; k--) {      // huling sub ay tinatapos ng save/check detection
                const sb = st.subs[k]; let ok = false;
                try { ok = !!sb.done(); } catch (e) {}
                if (ok && sb.hold && k === tutSubIdx && Date.now() - tutSubStart < sb.hold) ok = false;
                if (ok) { i = k + 1; break; }
            }
            if (i !== tutSubIdx) {
                tutSubIdx = i; tutSubStart = Date.now();
                tutStray = 0; tutArmIdle(); tutShowHint();
                const spot = document.getElementById('tutSpot');
                spot.classList.add('glide'); setTimeout(function () { spot.classList.remove('glide'); }, 500);
                if (tutMode === 'focus') setTimeout(function () { tutScrollToTarget(false); }, 60);
            }
        }
        setInterval(tutSubTick, 250);
        setInterval(function () { if (tutMode === 'focus' || tutMode === 'relaxed') tutShowHint(); }, 400);
        document.addEventListener('change', function (e) { if (e.target && e.target.id) tutChanged[e.target.id] = Date.now(); }, true);

        function tutTrackLoop() {
            const spot = document.getElementById('tutSpot');
            const card = document.getElementById('tutCard');
            (function frame() {
                if (tutMode !== 'focus' && tutMode !== 'relaxed') return;
                const r = tutRect();
                spot.style.visibility = document.querySelector('.modal-overlay.active:not([id^="formPopup_"])') ? 'hidden' : '';
                if (r) {
                    const pad = 6;
                    spot.style.left = (r.l - pad) + 'px'; spot.style.top = (r.t - pad) + 'px';
                    spot.style.width = (r.r - r.l + pad * 2) + 'px'; spot.style.height = (r.b - r.t + pad * 2) + 'px';
                    spot.style.display = '';
                    // iwas takip: kung natatakpan ng pop up ang button, ilipat sa taas/baba
                    const cr = card.getBoundingClientRect(), now = Date.now();
                    if (now - tutLastFlip > 800 && !(r.b + pad < cr.top - 8 || r.t - pad > cr.bottom + 8)) {
                        card.classList.toggle('top'); tutLastFlip = now;
                    }
                } else {
                    spot.style.display = 'none';
                }
                tutRaf = requestAnimationFrame(frame);
            })();
        }

        function tutInZone(el) {
            const st = tutCurStep(); if (!st || !el || !el.closest) return false;
            if (st.zone && el.closest(st.zone)) return true;
            return tutTargets(tutCurSel()).some(function (t) { return t === el || t.contains(el); });
        }

        // Nagbabantay kung sinusunod ba ng user ang step
        (function () {
            const card = document.getElementById('tutCard');
            document.addEventListener('pointerdown', function (e) {
                if (!tutState || tutState.finished || tutState.closed) return;
                if (tutMode !== 'intro' && tutMode !== 'focus') return;
                const t = e.target;
                if (card.contains(t)) { tutArmIdle(); return; }
                if (t.closest && t.closest('.modal-overlay.active')) { tutArmIdle(); return; }   // dialog ng step (hal. Name)
                if (tutMode === 'intro') { tutRelax(); return; }                              // pinindot ang madilim na paligid
                if (tutInZone(t)) { tutStray = 0; tutArmIdle(); return; }                      // sinusunod
                tutStray++;                                                                    // ibang lugar ang pinindot
                if (tutStray >= TUT_STRAY_LIMIT) tutRelax();
            }, true);
            ['keydown', 'input'].forEach(function (ev) {
                document.addEventListener(ev, function (e) {
                    if (tutMode === 'focus' && tutInZone(e.target)) tutArmIdle();
                }, true);
            });
        })();

        // Detect when the user really used each feature (wrap the save/check functions)
        (function () {
            function wrapSave(fnName, getList, stepId) {
                const orig = window[fnName];
                if (typeof orig !== 'function') return;
                window[fnName] = function () {
                    const before = JSON.stringify(getList());
                    const r = orig.apply(this, arguments);
                    Promise.resolve(r).then(() => { if (JSON.stringify(getList()) !== before) tutMarkDone(stepId); });
                    return r;
                };
            }
            wrapSave('saveCodeItem', () => savedCodes, 'add');
            wrapSave('saveJournalPost', () => journalPostsList, 'journal');
            wrapSave('saveStickyNote', () => stickyNotesList, 'sticky');
            wrapSave('saveBibleVerse', () => biblePostsList, 'bible');
            const origCheck = window.checkAnswerAndHighlight;
            if (typeof origCheck === 'function') {
                window.checkAnswerAndHighlight = function () {
                    const had = !!document.getElementById('notepadInput').value.trim();
                    const r = origCheck.apply(this, arguments);
                    if (had) tutMarkDone('test');
                    return r;
                };
            }
            // profile step: poll saved name/section
            tutPoll = setInterval(function () {
                if (!tutState || tutState.finished || tutState.closed) return;
                const cur = TUT_STEPS[tutState.step];
                if (cur && cur.check && cur.check()) tutMarkDone(cur.id);
            }, 700);
        })();

        // Decide on page load whether to show the tutorial (called after "Continue to App")
        function maybeStartTutorial() {
            let saved = null;
            try { saved = JSON.parse(localStorage.getItem('mindspaceTutorial') || 'null'); } catch (e) {}
            if (saved && !saved.finished && !saved.closed) { tutState = saved; renderTutorial(); return; }
            if (!saved && IS_FIRST_TIME) startTutorial(true);
        }

        function closeLoadingScreen() {
            document.getElementById('loading-screen').classList.add('hidden');
            try { localStorage.removeItem('mindspaceFirstRunPending'); } catch (e) {}
            // v1.86: sa phone lang lalabas ang Desktop/Mobile chooser; sa laptop/desktop diretso na sa app
            if (isPhoneDevice()) openViewChooser();
            else afterLoadingContinue();
        }

        function afterLoadingContinue() {
            setTimeout(maybeStartTutorial, 500);
            // Mobile lang at pagkatapos ng startup mag-uumpisa ang lightweight lag monitor.
            if (isPhoneDevice()) setTimeout(startMobileLagMonitor, 12000);
            // v1.64: pagkatapos ng loading screen, lalabas ang Recap Journal notification sa taas
            setTimeout(() => { if (journalStoryIsAvailable() && !journalStoryToastSeen) { journalStoryToastSeen = true; showRecapToast(); } }, 700);
        }

        /* ===== v1.86: VIEW MODE CHOOSER (phone / touch device lang) ===== */
        function isPhoneDevice() {
            try {
                return window.matchMedia('(hover: none) and (pointer: coarse)').matches;   // touch-only device (phone/tablet)
            } catch (e) { return false; }
        }

        function openViewChooser() {
            const cur = document.body.classList.contains('mobile-mode') ? 'mobile' : 'desktop';
            const mb = document.getElementById('vcMobileBtn'), db = document.getElementById('vcDesktopBtn');
            if (mb) mb.classList.toggle('vc-last', cur === 'mobile');
            if (db) db.classList.toggle('vc-last', cur === 'desktop');
            document.getElementById('viewChooserModal').classList.add('active');
        }

        function chooseViewMode(mode) {
            const isMobile = document.body.classList.contains('mobile-mode');
            if ((mode === 'mobile') !== isMobile) toggleViewMode();   // gamitin ang existing toggle (nagse-save + nag-uupdate ng button)
            document.getElementById('viewChooserModal').classList.remove('active');
            afterLoadingContinue();
        }

        let viewModePreviewActive = false;
        function toggleViewMode(showPreview = true) {
            if (viewModePreviewActive) return;
            const isMobile = document.body.classList.contains('mobile-mode');
            const nextMode = isMobile ? 'desktop' : 'mobile';
            const viewBtn = document.getElementById('viewModeBtn');
            const preview = showPreview ? showViewModePreview(nextMode) : null;
            if (preview) viewModePreviewActive = true;
            const applyMode = () => {
                if (nextMode === 'desktop') {
                    document.body.classList.remove('mobile-mode');
                    localStorage.setItem('appViewMode', 'desktop');
                    if (viewBtn) viewBtn.innerHTML = `<i class="fa-solid fa-mobile-screen-button"></i> <span class="tab-label">Mobile Mode</span>`;
                } else {
                    document.body.classList.add('mobile-mode');
                    localStorage.setItem('appViewMode', 'mobile');
                    if (viewBtn) viewBtn.innerHTML = `<i class="fa-solid fa-desktop"></i> <span class="tab-label">Desktop Mode</span>`;
                }
                syncAppExitGuard();
                syncRightSidebarForTab(document.getElementById('tabStickyBtn')?.classList.contains('active') ? 'sticky' : 'other');
            };
            if (!preview) { applyMode(); return; }
            const setProgress = value => {
                const percent = Math.max(0, Math.min(100, Math.round(value)));
                const progress = preview.querySelector('.theme-preview-progress');
                const track = preview.querySelector('.theme-preview-progress-track');
                const fill = preview.querySelector('.theme-preview-progress-fill');
                if (progress) progress.textContent = `${percent}%`;
                if (track) track.setAttribute('aria-valuenow', String(percent));
                if (fill) fill.style.width = `${percent}%`;
            };
            setProgress(12);
            requestAnimationFrame(() => {
                setProgress(35);
                requestAnimationFrame(() => {
                    applyMode();
                    setProgress(100);
                    window.setTimeout(() => {
                        preview.classList.add('closing');
                        window.setTimeout(() => {
                            preview.remove();
                            viewModePreviewActive = false;
                        }, 760);
                    }, 3000);
                });
            });
        }
        function loadViewMode() {
            const savedView = localStorage.getItem('appViewMode') || 'desktop';
            const viewBtn = document.getElementById('viewModeBtn');

            if (savedView === 'mobile') {
                document.body.classList.add('mobile-mode');
                viewBtn.innerHTML = `<i class="fa-solid fa-desktop"></i> <span class="tab-label">Desktop Mode</span>`;
            } else {
                document.body.classList.remove('mobile-mode');
                viewBtn.innerHTML = `<i class="fa-solid fa-mobile-screen-button"></i> <span class="tab-label">Mobile Mode</span>`;
            }
            syncAppExitGuard();
            syncRightSidebarForTab(document.getElementById('tabStickyBtn')?.classList.contains('active') ? 'sticky' : 'other');
        }

        // v2.27: no exit confirmation. Browser/app navigation and restart are direct.
        // The old beforeunload and mobile popstate confirmation were removed so
        // Full MindSpace Code can restart without an extra "Are you sure" prompt.
        function armAppExitGuard() { appExitGuardActive = false; }
        function syncAppExitGuard() { appExitGuardActive = false; }
        function refreshProfilePlaceholders() {
            const n = document.getElementById('displayName'), sec = document.getElementById('displaySection');
            n.classList.toggle('is-placeholder', n.textContent.trim() === PLACEHOLDER_NAME);
            sec.classList.toggle('is-placeholder', sec.textContent.trim() === PLACEHOLDER_SECTION);
        }

        async function loadProfileData() {
            const savedName = localStorage.getItem('profileName');
            const savedSection = localStorage.getItem('profileSection');
            const savedLogo = await MindSpaceMedia.get('profileLogoImg');
            const savedBanner = await MindSpaceMedia.get('profileBannerImg');

            if (savedName) document.getElementById('displayName').textContent = savedName;
            if (savedSection) document.getElementById('displaySection').textContent = savedSection;
            refreshProfilePlaceholders();
            if (savedLogo) document.getElementById('profileImage').src = savedLogo;
            else document.getElementById('profileImage').src = DEFAULT_AVATAR;
            if (savedBanner) {
                document.getElementById('bannerDisplay').style.backgroundImage = `url(${savedBanner})`;
                try { const img = await loadImageEl(savedBanner); bannerImgRatio = img.naturalHeight / img.naturalWidth; } catch (_) {}
            }
            try {
                const profileImage = document.getElementById('profileImage');
                if (profileImage && typeof profileImage.decode === 'function') await profileImage.decode();
            } catch (_) {}
            updateMediaControls();
        }

        const DEFAULT_AVATAR = "data:image/svg+xml;utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 150 150'%3E%3Crect width='150' height='150' fill='%23d5dbe3'/%3E%3Ccircle cx='75' cy='58' r='26' fill='%23fff'/%3E%3Cpath d='M23 150c0-33 22-54 52-54s52 21 52 54z' fill='%23fff'/%3E%3C/svg%3E";

        // Shows the remove (trash) buttons only when a custom picture/banner exists
        function updateMediaControls() {
            const hasPic = MindSpaceMedia.has('profileLogoImg');
            const hasBanner = MindSpaceMedia.has('profileBannerImg');
            document.querySelector('.profile-pic-container').classList.toggle('has-custom', hasPic);
            document.getElementById('bannerDisplay').classList.toggle('has-custom', hasBanner);
            document.getElementById('removeProfileBtn').classList.toggle('hidden', !hasPic);
            document.getElementById('removeBannerBtn').classList.toggle('hidden', !hasBanner);
        }

        // ---------- small image helpers ----------
        function fileToDataURL(file) {
            return new Promise((res, rej) => {
                const r = new FileReader();
                r.onload = () => res(r.result);
                r.onerror = rej;
                r.readAsDataURL(file);
            });
        }
        function loadImageEl(src) {
            return new Promise((res, rej) => {
                const i = new Image();
                i.onload = () => res(i);
                i.onerror = rej;
                i.src = src;
            });
        }
        async function safeStore(key, value) {
            const ok = await MindSpaceMedia.set(key, value);
            if (!ok) showCustomAlert('Not enough browser storage to save this picture. Try a smaller image.', 'Storage Full');
            return ok;
        }

        async function removeProfilePic() {
            if (!(await showCustomConfirm('Remove your profile picture?', 'Remove Profile Picture'))) return;
            await MindSpaceMedia.remove('profileLogoImg');
            document.getElementById('profileImage').src = DEFAULT_AVATAR;
            document.getElementById('logoInput').value = '';
            invalidateMindSpaceStartupWarm('feed', 'journal', 'bible');
            updateMediaControls();
        }

        async function removeBanner() {
            if (!(await showCustomConfirm('Remove your banner photo?', 'Remove Banner'))) return;
            await MindSpaceMedia.remove('profileBannerImg');
            localStorage.removeItem('bannerPosY');
            bannerPosY = 50; bannerImgRatio = 0;
            document.getElementById('bannerDisplay').style.backgroundImage = '';
            document.getElementById('bannerDisplay').style.backgroundPositionY = '50%';
            document.getElementById('bannerInput').value = '';
            updateMediaControls();
        }

        async function editInfo(field) {
            if (field === 'name') {
                let current = document.getElementById('displayName').textContent;
                if (current.trim() === PLACEHOLDER_NAME) current = '';
                const newName = await showCustomPrompt("Enter your Name:", current, "Edit Name");
                if (newName && newName.trim() !== "") {
                    document.getElementById('displayName').textContent = newName.trim();
                    localStorage.setItem('profileName', newName.trim());
                    invalidateMindSpaceStartupWarm('feed', 'journal', 'bible');
                    refreshProfilePlaceholders();
                }
            } else if (field === 'section') {
                let current = document.getElementById('displaySection').textContent;
                if (current.trim() === PLACEHOLDER_SECTION) current = '';
                const newSec = await showCustomPrompt("Enter your Year & Section:", current, "Edit Year & Section");
                if (newSec && newSec.trim() !== "") {
                    document.getElementById('displaySection').textContent = newSec.trim();
                    localStorage.setItem('profileSection', newSec.trim());
                    refreshProfilePlaceholders();
                }
            }
        }

        // ---------- Study Music: up to three locally stored MP3 tracks ----------
        function studyMusicMetaNames() {
            try { const names = JSON.parse(localStorage.getItem('studyMusicTrackNames') || '[]'); return Array.isArray(names) ? names : []; }
            catch (_) { return []; }
        }
        // Built-in default tracks (embedded in #studyMusicBuiltInData at the end of this file). They are always
        // available, cannot be removed, and do not count toward the 3 uploaded-track limit.
        function studyMusicUserTracks() { return studyMusicTracks.filter(t => !t.builtIn); }
        function studyMusicTrackIds() { try { const a=JSON.parse(localStorage.getItem('studyMusicTrackIds')||'[]'); return Array.isArray(a)?a:[]; } catch (_) { return []; } }
        function studyMusicPlaylists() { try { const a=JSON.parse(localStorage.getItem('studyMusicPlaylists')||'[]'); return Array.isArray(a)?a:[]; } catch (_) { return []; } }
        function saveStudyMusicPlaylists(value) { localStorage.setItem('studyMusicPlaylists',JSON.stringify(value)); }
        function studyMusicBuiltInTracks() {
            try {
                const el = document.getElementById('studyMusicBuiltInData');
                const items = JSON.parse((el && el.textContent) || '[]');
                return items.map(item => {
                    const bin = atob(item.b64), bytes = new Uint8Array(bin.length);
                    for (let i=0; i<bin.length; i++) bytes[i] = bin.charCodeAt(i);
                    const blob = new Blob([bytes], {type:'audio/mpeg'});
                    return {name:item.name, blob, url:URL.createObjectURL(blob), builtIn:true};
                });
            } catch (e) { console.warn('[Study Music] Could not load built-in tracks', e); return []; }
        }
        async function loadStudyMusicTracks() {
            if (studyMusicTracksLoaded) return studyMusicTracks;
            if (studyMusicLoadPromise) return studyMusicLoadPromise;
            studyMusicLoadPromise = (async () => {
                studyMusicTracks.push(...studyMusicBuiltInTracks());
                const names = studyMusicMetaNames();
                let ids = studyMusicTrackIds();
                for (let i=0; i<names.length; i++) {
                    try {
                        const blob = await MindSpaceMedia.get('studyMusicTrack_' + i);
                        if (!blob) continue;
                        const audioBlob = blob instanceof Blob ? blob : new Blob([blob], {type:'audio/mpeg'});
                        if (!ids[i]) ids[i]='track-'+Date.now()+'-'+i+'-'+Math.random().toString(36).slice(2,8);
                        studyMusicTracks.push({id:ids[i],name:String(names[i] || ('Study Track ' + (i+1))), blob:audioBlob, url:URL.createObjectURL(audioBlob)});
                    } catch (e) { console.warn('[Study Music] Could not load track', i, e); }
                }
                localStorage.setItem('studyMusicTrackIds',JSON.stringify(ids.slice(0,studyMusicUserTracks().length)));
                studyMusicTracksLoaded = true;
                return studyMusicTracks;
            })();
            try { return await studyMusicLoadPromise; }
            finally { studyMusicLoadPromise = null; }
        }
        function renderStudyMusicList() {
            const list = document.getElementById('studyMusicList');
            const count = document.getElementById('studyMusicTrackCount');
            const crossfade = document.getElementById('studyMusicCrossfade');
            if (!list) return;
            if (count) count.textContent = `${studyMusicUserTracks().length} uploaded`;
            renderStudyMusicPlaylists();
            if (crossfade) crossfade.checked = studyMusicCrossfade;
            const crossfadeLabel = document.getElementById('studyMusicCrossfadeLabel');
            if (crossfadeLabel) crossfadeLabel.textContent = studyMusicCrossfade ? 'On' : 'Off';
            syncSfxSlider();
            const volume = document.getElementById('studyMusicVolume');
            if (volume) volume.value = String(Math.round(studyMusicVolume*100));
            const volumeMini = document.getElementById('studyMusicMiniVolume');
            if (volumeMini) volumeMini.value = String(Math.round(studyMusicVolume*100));
            const volumeLabel = document.getElementById('studyMusicVolumeLabel');
            if (volumeLabel) volumeLabel.textContent = Math.round(studyMusicVolume*100)+'%';
            const selectedPlaylist=document.getElementById('studyMusicPlaylistSelect')?.value||'';
            const playlist=studyMusicPlaylists().find(p=>p.id===selectedPlaylist);
            const shownTracks=playlist ? studyMusicTracks.filter(t=>!t.builtIn && playlist.trackIds.includes(t.id)) : studyMusicTracks;
            list.innerHTML = shownTracks.length ? shownTracks.map(track=>{ const i=studyMusicTracks.indexOf(track); return `<div class="study-music-track${i===studyMusicCurrentIndex?' active':''}"><span class="study-music-track-name" title="${escapeHtml(track.name)}"><i class="fa-solid fa-music"></i> ${escapeHtml(track.name)}</span>${track.builtIn?'<span class="study-music-badge">Built-in</span>':''}<button type="button" onclick="playStudyMusicTrack(${i})" aria-label="Play ${escapeHtml(track.name)}"><i class="fa-solid fa-play"></i></button>${track.builtIn?'':`<button type="button" onclick="toggleStudyMusicPlaylistTrack(${i})" title="Add/remove from selected playlist"><i class="fa-solid fa-list-check"></i></button><button type="button" onclick="removeStudyMusicTrack(${i})" aria-label="Remove ${escapeHtml(track.name)}"><i class="fa-solid fa-trash"></i></button>`}</div>`; }).join('') : '<div class="study-music-empty"><i class="fa-solid fa-headphones"></i><br><br>No tracks in this playlist.</div>';
            const status = document.getElementById('studyMusicStatus');
            if (status && studyMusicCurrentIndex >= 0 && studyMusicTracks[studyMusicCurrentIndex]) status.textContent = 'Now playing: ' + studyMusicTracks[studyMusicCurrentIndex].name;
            updateStudyMusicDisplays();
        }
        function openStudyMusic() {
            closeMediaMenu();
            closeOtherPopups('studyMusicModal');
            document.getElementById('studyMusicModal').classList.add('active');
            loadStudyMusicTracks().then(renderStudyMusicList).catch(() => showCustomAlert('Could not load the saved study music tracks.', 'Study Music'));
        }
        function closeStudyMusic() { document.getElementById('studyMusicModal').classList.remove('active'); }
        async function persistStudyMusicTracks() {
            const userTracks = studyMusicUserTracks();
            for (let i=0; i<userTracks.length; i++) {
                const ok = await MindSpaceMedia.set('studyMusicTrack_' + i, userTracks[i].blob);
                if (!ok) throw new Error('Browser storage is full.');
            }
            const previousCount=studyMusicMetaNames().length;
            for (let i=userTracks.length; i<previousCount; i++) await MindSpaceMedia.remove('studyMusicTrack_' + i);
            localStorage.setItem('studyMusicTrackNames', JSON.stringify(userTracks.map(t=>t.name)));
            localStorage.setItem('studyMusicTrackIds', JSON.stringify(userTracks.map(t=>t.id || ('track-'+Date.now()+'-'+Math.random().toString(36).slice(2,8)))));
        }
        async function addStudyMusicFiles(fileList) {
            await loadStudyMusicTracks();
            const candidates = Array.from(fileList || []).filter(file => file && (/\.mp3$/i.test(file.name) || file.type === 'audio/mpeg'));
            const accepted = candidates;
            if (!accepted.length) {
                showCustomAlert('Please select one or more MP3 audio files.', 'MP3 Files Only');
                document.getElementById('studyMusicFileInput').value = '';
                return;
            }
            try {
                for (const file of accepted) studyMusicTracks.push({id:'track-'+Date.now()+'-'+Math.random().toString(36).slice(2,10),name:file.name, blob:file, url:URL.createObjectURL(file)});
                await persistStudyMusicTracks();
                renderStudyMusicList();
                document.getElementById('studyMusicStatus').textContent = `Added ${accepted.length} MP3 track(s).`; 
            } catch (e) {
                studyMusicTracks.splice(Math.max(0,studyMusicTracks.length-accepted.length),accepted.length);
                renderStudyMusicList();
                showCustomAlert('Could not save the MP3 file(s). Check available browser storage and try smaller files.', 'Storage Full');
            }
            document.getElementById('studyMusicFileInput').value = '';
        }
        function renderStudyMusicPlaylists() {
            const select=document.getElementById('studyMusicPlaylistSelect'); if(!select) return;
            const playlists=studyMusicPlaylists();
            let current=localStorage.getItem('studyMusicSelectedPlaylist')||select.value||'';
            if(!playlists.some(p=>p.id===current)) current='';
            select.innerHTML='<option value="">All tracks</option>'+playlists.map(p=>'<option value="'+escapeHtml(p.id)+'">'+escapeHtml(p.name)+'</option>').join('');
            select.value=current;
            try { localStorage.setItem('studyMusicSelectedPlaylist',current); } catch(_) {}
        }
        function selectStudyMusicPlaylist(id) {
            try { localStorage.setItem('studyMusicSelectedPlaylist',id||''); } catch(_) {}
            renderStudyMusicList();
        }
        function createStudyMusicPlaylist() {
            const name=prompt('Pangalan ng bagong playlist:'); if(!name||!name.trim()) return;
            const list=studyMusicPlaylists(); const id='playlist-'+Date.now()+'-'+Math.random().toString(36).slice(2,8);
            list.push({id,name:name.trim().slice(0,80),trackIds:[]}); saveStudyMusicPlaylists(list);
            try { localStorage.setItem('studyMusicSelectedPlaylist',id); } catch(_) {}
            renderStudyMusicList();
        }
        function addTracksToStudyMusicPlaylist() {
            const sel=document.getElementById('studyMusicPlaylistSelect'), list=studyMusicPlaylists(), p=list.find(x=>x.id===sel?.value);
            if(!p) { showCustomAlert('Pumili o gumawa muna ng playlist.', 'Playlist'); return; }
            const tracks=studyMusicUserTracks();
            if(!tracks.length) { showCustomAlert('Mag-upload muna ng MP3 bago magdagdag sa playlist.', 'Playlist'); return; }
            const menu=tracks.map((t,i)=>`${i+1}. ${t.name}${(p.trackIds||[]).includes(t.id)?' ✓':''}`).join('\n');
            const answer=prompt('Ilagay ang number ng kanta na idaragdag o aalisin. Para sa maraming kanta, paghiwalayin ng comma.\n\n'+menu);
            if(!answer) return;
            const indexes=answer.split(',').map(v=>Number(v.trim())-1).filter(i=>Number.isInteger(i)&&i>=0&&i<tracks.length);
            if(!indexes.length) { showCustomAlert('Walang valid na song number.', 'Playlist'); return; }
            p.trackIds=Array.isArray(p.trackIds)?p.trackIds:[];
            for(const i of new Set(indexes)) { const id=tracks[i].id; p.trackIds=p.trackIds.includes(id)?p.trackIds.filter(x=>x!==id):p.trackIds.concat(id); }
            saveStudyMusicPlaylists(list); renderStudyMusicList();
        }
        function deleteStudyMusicPlaylist() {
            const sel=document.getElementById('studyMusicPlaylistSelect'), id=sel&&sel.value; if(!id) return;
            saveStudyMusicPlaylists(studyMusicPlaylists().filter(p=>p.id!==id));
            try { localStorage.setItem('studyMusicSelectedPlaylist',''); } catch(_) {}
            renderStudyMusicList();
        }
        function toggleStudyMusicPlaylistTrack(index) {
            const track=studyMusicTracks[index], sel=document.getElementById('studyMusicPlaylistSelect'); if(!track||track.builtIn||!sel||!sel.value) { showCustomAlert('Pumili o gumawa muna ng playlist.', 'Playlist'); return; }
            const list=studyMusicPlaylists(), p=list.find(x=>x.id===sel.value); if(!p) return;
            p.trackIds=Array.isArray(p.trackIds)?p.trackIds:[];
            p.trackIds=p.trackIds.includes(track.id)?p.trackIds.filter(id=>id!==track.id):[...p.trackIds,track.id];
            saveStudyMusicPlaylists(list); renderStudyMusicList();
        }
        async function playStudyMusicPlaylist() {
            const sel=document.getElementById('studyMusicPlaylistSelect'), pid=localStorage.getItem('studyMusicSelectedPlaylist')||sel?.value, p=studyMusicPlaylists().find(x=>x.id===pid);
            if(!p) { showCustomAlert('Pumili muna ng playlist.', 'Playlist'); return; }
            const first=studyMusicTracks.findIndex(t=>!t.builtIn&&p.trackIds.includes(t.id));
            if(first<0) { showCustomAlert('Wala pang kanta sa playlist na ito. Piliin ang list icon sa tabi ng uploaded track para idagdag.', 'Playlist'); return; }
            await playStudyMusicTrack(first);
        }
        function blobToBase64(blob) { return new Promise((resolve,reject)=>{ const r=new FileReader(); r.onload=()=>resolve(String(r.result).split(',')[1]||''); r.onerror=()=>reject(r.error); r.readAsDataURL(blob); }); }
        async function buildStudyMusicBackupPayload() {
            await loadStudyMusicTracks(); const tracks=[];
            for(const t of studyMusicUserTracks()) tracks.push({id:t.id,name:t.name,type:t.blob.type||'audio/mpeg',data:await blobToBase64(t.blob)});
            return {format:'MindSpaceMusicBackup',version:1,tracks,playlists:studyMusicPlaylists()};
        }
        async function restoreStudyMusicBackupPayload(music) {
            if(!music) return false;
            if(music.format!=='MindSpaceMusicBackup'||music.version!==1||!Array.isArray(music.tracks)||!Array.isArray(music.playlists)) throw new Error('Invalid music data in backup.');
            await loadStudyMusicTracks();
            const imported=music.tracks.map((t,i)=>{ if(!t||typeof t.data!=='string'||typeof t.name!=='string') throw new Error('Invalid music track data.'); const raw=atob(t.data),bytes=new Uint8Array(raw.length); for(let j=0;j<raw.length;j++) bytes[j]=raw.charCodeAt(j); return {id:String(t.id||('track-import-'+Date.now()+'-'+i)),name:t.name,blob:new Blob([bytes],{type:t.type||'audio/mpeg'}),url:''}; });
            if(studyMusicUserTracks().length) { const replace=await showCustomConfirm(`This backup contains ${imported.length} uploaded music track(s) and ${music.playlists.length} playlist(s). Replace the uploaded tracks/playlists currently on this device?`, 'Import Music', {okLabel:'Replace Music',cancelLabel:'Keep Current'}); if(!replace) return false; }
            studyMusicDecks.forEach(d=>d.audio.pause()); studyMusicDecks.forEach(d=>{d.audio.removeAttribute('src');d.audio.load();}); studyMusicActiveDeck=-1; studyMusicCurrentIndex=-1; studyMusicAutoFadeIndex=-1;
            studyMusicTracks.forEach(t=>{if(t.url)URL.revokeObjectURL(t.url)});
            studyMusicTracks=studyMusicBuiltInTracks().concat(imported.map(t=>({...t,url:URL.createObjectURL(t.blob)})));
            saveStudyMusicPlaylists(music.playlists.filter(p=>p&&typeof p.name==='string').map(p=>({id:String(p.id||('playlist-'+Math.random().toString(36).slice(2))),name:p.name.slice(0,80),trackIds:Array.isArray(p.trackIds)?p.trackIds.map(String):[]})));
            await persistStudyMusicTracks(); renderStudyMusicList(); updateStudyMusicPlayButton(); return true;
        }
        async function exportStudyMusicBackup() {
            try {
                await loadStudyMusicTracks();
                const music=await buildStudyMusicBackupPayload();
                const backup={...music,createdAt:new Date().toISOString()};
                const blob=new Blob([JSON.stringify(backup)],{type:'application/json'}), url=URL.createObjectURL(blob), a=document.createElement('a');
                a.href=url; a.download='MindSpace_Music_Backup_'+new Date().toISOString().slice(0,10)+'.json'; document.body.appendChild(a); a.click(); a.remove(); setTimeout(()=>URL.revokeObjectURL(url),1000);
                const status=document.getElementById('studyMusicStatus'); if(status) status.textContent='Music backup exported. Keep this JSON file with your MindSpace HTML.';
            } catch(e) { showCustomAlert('Hindi nagawa ang backup. Baka puno na ang storage o masyadong malaki ang files.', 'Export Failed'); }
        }
        async function importStudyMusicBackup(file) {
            const input=document.getElementById('studyMusicBackupInput');
            try {
                if(!file) return;
                const data=JSON.parse(await file.text());
                if(data.format!=='MindSpaceMusicBackup'||data.version!==1||!Array.isArray(data.tracks)||!Array.isArray(data.playlists)) throw new Error('Invalid backup file');
                
                await loadStudyMusicTracks();
                const imported=data.tracks.map((t,i)=>{ if(!t||typeof t.data!=='string'||typeof t.name!=='string') throw new Error('Invalid track data'); const raw=atob(t.data), bytes=new Uint8Array(raw.length); for(let j=0;j<raw.length;j++) bytes[j]=raw.charCodeAt(j); return {id:String(t.id||('track-import-'+Date.now()+'-'+i)),name:t.name,blob:new Blob([bytes],{type:t.type||'audio/mpeg'}),url:''}; });
                studyMusicDecks.forEach(d=>d.audio.pause()); studyMusicDecks.forEach(d=>{d.audio.removeAttribute('src');d.audio.load();}); studyMusicActiveDeck=-1; studyMusicCurrentIndex=-1; studyMusicAutoFadeIndex=-1;
                studyMusicTracks.forEach(t=>{if(t.url)URL.revokeObjectURL(t.url)});
                studyMusicTracks=studyMusicBuiltInTracks().concat(imported.map(t=>({...t,url:URL.createObjectURL(t.blob)})));
                saveStudyMusicPlaylists(data.playlists.filter(p=>p&&typeof p.name==='string').map(p=>({id:String(p.id||('playlist-'+Math.random().toString(36).slice(2))),name:p.name.slice(0,80),trackIds:Array.isArray(p.trackIds)?p.trackIds.map(String):[]})));
                await persistStudyMusicTracks(); renderStudyMusicList(); updateStudyMusicPlayButton();
                const status=document.getElementById('studyMusicStatus'); if(status) status.textContent='Imported '+imported.length+' track(s) and playlist(s).';
            } catch(e) { showCustomAlert('Hindi ma-import ang music backup: '+(e.message||'invalid file'), 'Import Failed'); }
            finally { if(input) input.value=''; }
        }
        function setStudyMusicCrossfade(enabled) {
            studyMusicCrossfade = !!enabled;
            try { localStorage.setItem('studyMusicCrossfade', studyMusicCrossfade ? '1' : '0'); } catch (_) {}
            const label=document.getElementById('studyMusicCrossfadeLabel');
            if (label) label.textContent=studyMusicCrossfade ? 'On' : 'Off';
        }
        function setStudyMusicVolume(value) {
            const n=Number(value);
            studyMusicVolume=Number.isFinite(n) ? Math.max(0,Math.min(1,n)) : .65;
            try { localStorage.setItem('studyMusicVolume', String(studyMusicVolume)); } catch (_) {}
            if (studyMusicMasterGain && studyMusicAudioContext) {
                const now=studyMusicAudioContext.currentTime;
                studyMusicMasterGain.gain.cancelScheduledValues(now);
                studyMusicMasterGain.gain.setTargetAtTime(studyMusicVolume,now,.025);
            }
            const volume=document.getElementById('studyMusicVolume'); if (volume) volume.value=String(Math.round(studyMusicVolume*100));
            const mini=document.getElementById('studyMusicMiniVolume'); if (mini) mini.value=String(Math.round(studyMusicVolume*100));
            const label=document.getElementById('studyMusicVolumeLabel'); if (label) label.textContent=Math.round(studyMusicVolume*100)+'%';
            /* The slider controls quiz background music only; timer SFX stays at a fixed level. */
            if (window.bsitMusic && bsitMusic.setVolume) bsitMusic.setVolume(studyMusicVolume);
        }
        function setupStudyMusicAudio() {
            if (studyMusicDecks.length) return true;
            const AudioContextClass = window.AudioContext || window.webkitAudioContext;
            if (!AudioContextClass) return false;
            try {
                studyMusicAudioContext = new AudioContextClass();
                studyMusicMasterGain = studyMusicAudioContext.createGain();
                studyMusicMasterGain.gain.value = studyMusicVolume;
                studyMusicMasterGain.connect(studyMusicAudioContext.destination);
                ['studyMusicAudioA','studyMusicAudioB'].forEach(id => {
                    const audio = document.getElementById(id);
                    const source = studyMusicAudioContext.createMediaElementSource(audio);
                    const gain = studyMusicAudioContext.createGain();
                    gain.gain.value = 0;
                    source.connect(gain); gain.connect(studyMusicMasterGain);
                    studyMusicDecks.push({audio,gain});
                    audio.addEventListener('timeupdate', () => {
                        const isActive = studyMusicDecks[studyMusicActiveDeck]?.audio === audio;
                        if (isActive) updateStudyMusicProgress(audio);
                        if (!isActive || studyMusicSeeking || !studyMusicCrossfade || studyMusicTracks.length < 2 || studyMusicCurrentIndex < 0 || studyMusicAutoFadeIndex === studyMusicCurrentIndex) return;
                        const remaining = audio.duration - audio.currentTime;
                        if (isFinite(remaining) && remaining > 0 && remaining <= Math.min(2.5, Math.max(.5, audio.duration*.25))) {
                            studyMusicAutoFadeIndex = studyMusicCurrentIndex;
                            playStudyMusicTrack((studyMusicCurrentIndex+1)%studyMusicTracks.length, true, Math.min(2.5, remaining));
                        }
                    });
                    ['loadedmetadata','durationchange','seeked'].forEach(eventName => audio.addEventListener(eventName, () => {
                        if (studyMusicDecks[studyMusicActiveDeck]?.audio === audio) updateStudyMusicProgress(audio);
                    }));
                    audio.addEventListener('play', () => { if (studyMusicDecks[studyMusicActiveDeck]?.audio === audio) updateStudyMusicPlayButton(); });
                    audio.addEventListener('pause', () => { if (studyMusicDecks[studyMusicActiveDeck]?.audio === audio) updateStudyMusicPlayButton(); });
                    audio.addEventListener('ended', () => {
                        if (studyMusicDecks[studyMusicActiveDeck]?.audio === audio && studyMusicTracks.length > 1) playStudyMusicTrack((studyMusicCurrentIndex+1)%studyMusicTracks.length, true);
                        else if (studyMusicDecks[studyMusicActiveDeck]?.audio === audio) updateStudyMusicPlayButton();
                    });
                });
                return true;
            } catch (e) { console.warn('[Study Music] Audio setup failed', e); studyMusicDecks=[]; return false; }
        }
        function updateStudyMusicPlayButton() {
            const btn=document.getElementById('studyMusicPlayBtn');
            const audio=studyMusicDecks[studyMusicActiveDeck]?.audio;
            const playing=!!(audio && !audio.paused);
            if (btn) btn.innerHTML = playing ? '<i class="fa-solid fa-pause"></i> Pause' : '<i class="fa-solid fa-play"></i> Play';
            const mini=document.getElementById('studyMiniPlayBtn');
            if (mini) { mini.innerHTML=playing?'<i class="fa-solid fa-pause"></i>':'<i class="fa-solid fa-play"></i>'; mini.setAttribute('aria-label',playing?'Pause study music':'Play study music'); }
            ['studyMiniWave','studyMusicWave'].forEach(id => {
                const indicator=document.getElementById(id);
                if (indicator) { indicator.classList.toggle('is-playing',playing); indicator.setAttribute('aria-label',playing?'Music playing':'Music paused'); indicator.title=playing?'Music playing':'Music paused'; }
            });
            updateStudyMusicDisplays();
        }
        function formatStudyMusicTime(seconds) {
            if (!Number.isFinite(seconds) || seconds < 0) return '0:00';
            const total=Math.floor(seconds), hours=Math.floor(total/3600), minutes=Math.floor((total%3600)/60), secs=total%60;
            return hours ? `${hours}:${String(minutes).padStart(2,'0')}:${String(secs).padStart(2,'0')}` : `${minutes}:${String(secs).padStart(2,'0')}`;
        }
        function updateStudyMusicProgress(audio=studyMusicDecks[studyMusicActiveDeck]?.audio) {
            const duration=audio && Number.isFinite(audio.duration) ? audio.duration : 0;
            const current=audio && Number.isFinite(audio.currentTime) ? audio.currentTime : 0;
            ['studyMiniSeek','studyMusicSeek'].forEach(id => {
                const slider=document.getElementById(id);
                if (slider) { slider.max=String(duration); slider.value=String(Math.min(current,duration||0)); slider.disabled=duration<=0; }
            });
            ['studyMiniCurrentTime','studyMusicCurrentTime'].forEach(id => { const el=document.getElementById(id); if(el) el.textContent=formatStudyMusicTime(current); });
            ['studyMiniDuration','studyMusicDuration'].forEach(id => { const el=document.getElementById(id); if(el) el.textContent=formatStudyMusicTime(duration); });
        }
        function seekStudyMusic(value) {
            const audio=studyMusicDecks[studyMusicActiveDeck]?.audio;
            const target=Number(value);
            if (!audio || !Number.isFinite(audio.duration) || !Number.isFinite(target)) return;
            audio.currentTime=Math.max(0,Math.min(audio.duration,target));
            if (audio.currentTime < audio.duration - Math.min(2.5,Math.max(.5,audio.duration*.25))) studyMusicAutoFadeIndex=-1;
            updateStudyMusicProgress(audio);
        }
        function updateStudyMusicDisplays() {
            const name=document.getElementById('studyMiniTrackName');
            if (name) name.textContent=studyMusicCurrentIndex>=0 && studyMusicTracks[studyMusicCurrentIndex] ? studyMusicTracks[studyMusicCurrentIndex].name : studyMusicTracks.length ? `${studyMusicTracks.length} track${studyMusicTracks.length===1?'':'s'} ready` : '7 built-in tracks ready';
            const mini=document.getElementById('studyMusicMiniVolume'); if (mini) mini.value=String(Math.round(studyMusicVolume*100));
            const volume=document.getElementById('studyMusicVolume'); if (volume) volume.value=String(Math.round(studyMusicVolume*100));
            const label=document.getElementById('studyMusicVolumeLabel'); if (label) label.textContent=Math.round(studyMusicVolume*100)+'%';
            updateStudyMusicProgress();
        }
        async function miniToggleStudyMusicPlayback() {
            await loadStudyMusicTracks();
            if (!studyMusicTracks.length) { openStudyMusic(); return; }
            await toggleStudyMusicPlayback();
        }
        async function playStudyMusicTrack(index, automatic=false, requestedFadeSeconds=2.5) {
            await loadStudyMusicTracks();
            if (!studyMusicTracks[index]) return;
            if (!setupStudyMusicAudio()) { showCustomAlert('This browser does not support background audio playback.', 'Audio Not Available'); return; }
            try { await studyMusicAudioContext.resume(); } catch (_) {}
            if (studyMusicCurrentIndex === index && studyMusicActiveDeck >= 0) {
                const current = studyMusicDecks[studyMusicActiveDeck].audio;
                if (!current.paused) return;
                try { await current.play(); updateStudyMusicPlayButton(); return; } catch (_) {}
            }
            const oldIndex=studyMusicActiveDeck;
            const oldDeck=oldIndex>=0 ? studyMusicDecks[oldIndex] : null;
            const shouldFade=!!(studyMusicCrossfade && oldDeck && !oldDeck.audio.paused);
            const nextIndex=oldIndex<0 ? 0 : 1-oldIndex;
            const nextDeck=studyMusicDecks[nextIndex];
            studyMusicDecks.forEach((deck,i) => { if (i!==oldIndex && i!==nextIndex) { deck.audio.pause(); deck.gain.gain.cancelScheduledValues(studyMusicAudioContext.currentTime); deck.gain.gain.setValueAtTime(0,studyMusicAudioContext.currentTime); } });
            nextDeck.audio.pause(); nextDeck.audio.loop=studyMusicTracks.length===1; nextDeck.audio.src=studyMusicTracks[index].url; nextDeck.audio.load();
            const now=studyMusicAudioContext.currentTime;
            nextDeck.gain.gain.cancelScheduledValues(now); nextDeck.gain.gain.setValueAtTime(shouldFade ? 0 : 1,now);
            try { await nextDeck.audio.play(); }
            catch (e) { document.getElementById('studyMusicStatus').textContent='Could not play this MP3 in the current browser.'; return; }
            studyMusicActiveDeck=nextIndex; studyMusicCurrentIndex=index; studyMusicAutoFadeIndex=-1;
            if (shouldFade) {
                const fadeStart=studyMusicAudioContext.currentTime;
                const fadeSeconds=Math.max(.15,Math.min(2.5,Number(requestedFadeSeconds)||2.5));
                const end=fadeStart+fadeSeconds;
                nextDeck.gain.gain.cancelScheduledValues(fadeStart); nextDeck.gain.gain.setValueAtTime(0,fadeStart); nextDeck.gain.gain.linearRampToValueAtTime(1,end);
                oldDeck.gain.gain.cancelScheduledValues(fadeStart); oldDeck.gain.gain.setValueAtTime(oldDeck.gain.gain.value,fadeStart); oldDeck.gain.gain.linearRampToValueAtTime(0,end);
                setTimeout(() => { if (oldDeck.audio !== studyMusicDecks[studyMusicActiveDeck]?.audio) { oldDeck.audio.pause(); oldDeck.audio.currentTime=0; } },fadeSeconds*1000+120);
            } else if (oldDeck) { oldDeck.audio.pause(); oldDeck.gain.gain.cancelScheduledValues(now); oldDeck.gain.gain.setValueAtTime(0,now); }
            document.getElementById('studyMusicStatus').textContent=(automatic?'Crossfading to: ':'Now playing: ')+studyMusicTracks[index].name;
            renderStudyMusicList(); updateStudyMusicPlayButton();
        }
        function stepStudyMusic(direction) {
            if (!studyMusicTracks.length) { loadStudyMusicTracks().then(() => studyMusicTracks.length ? stepStudyMusic(direction) : renderStudyMusicList()); return; }
            const playlistId=localStorage.getItem('studyMusicSelectedPlaylist')||document.getElementById('studyMusicPlaylistSelect')?.value;
            const playlist=studyMusicPlaylists().find(p=>p.id===playlistId);
            const queue=playlist ? studyMusicTracks.map((t,i)=>({t,i})).filter(x=>!x.t.builtIn&&playlist.trackIds.includes(x.t.id)).map(x=>x.i) : studyMusicTracks.map((_,i)=>i);
            if(!queue.length) return;
            const pos=queue.indexOf(studyMusicCurrentIndex);
            const next=pos<0 ? (direction>0?queue[0]:queue[queue.length-1]) : queue[(pos+direction+queue.length)%queue.length];
            playStudyMusicTrack(next);
        }
        async function toggleStudyMusicPlayback() {
            await loadStudyMusicTracks();
            if (!studyMusicTracks.length) { renderStudyMusicList(); document.getElementById('studyMusicStatus').textContent='Add an MP3 track before pressing Play.'; return; }
            if (!setupStudyMusicAudio()) { showCustomAlert('This browser does not support background audio playback.', 'Audio Not Available'); return; }
            const current=studyMusicDecks[studyMusicActiveDeck]?.audio;
            if (current && !current.paused) {
                studyMusicDecks.forEach(deck=>deck.audio.pause());
                updateStudyMusicPlayButton();
            } else await playStudyMusicTrack(studyMusicCurrentIndex<0 ? 0 : studyMusicCurrentIndex);
        }
        async function removeStudyMusicTrack(index) {
            await loadStudyMusicTracks();
            if (!studyMusicTracks[index] || studyMusicTracks[index].builtIn) return;
            studyMusicDecks.forEach(deck=>deck.audio.pause());
            studyMusicDecks.forEach(deck=>{ deck.audio.removeAttribute('src'); deck.audio.load(); });
            studyMusicActiveDeck=-1; studyMusicCurrentIndex=-1; studyMusicAutoFadeIndex=-1;
            studyMusicTracks.forEach(track=>URL.revokeObjectURL(track.url));
            studyMusicTracks.splice(index,1);
            try {
                await persistStudyMusicTracks();
                studyMusicTracks=studyMusicTracks.map(track=>({...track,url:URL.createObjectURL(track.blob)}));
                document.getElementById('studyMusicStatus').textContent='Track removed.';
                renderStudyMusicList(); updateStudyMusicPlayButton();
            } catch (_) { showCustomAlert('Could not update the saved playlist.', 'Study Music'); }
        }

        // How many pixels the banner image can actually move up/down (background-size: cover)
        function getBannerOverflow(banner) {
            const w = banner.clientWidth, h = banner.clientHeight;
            if (!bannerImgRatio) return h;                 // fallback until the ratio is known
            return Math.max(0, w * bannerImgRatio - h);
        }

        function updateBannerSpotlight() {
            if (!isBannerRepositionMode) return;
            const banner = document.getElementById('bannerDisplay');
            const rect = banner.getBoundingClientRect();
            const x1 = Math.max(0, rect.left), y1 = Math.max(0, rect.top);
            const x2 = Math.min(window.innerWidth, rect.right), y2 = Math.min(window.innerHeight, rect.bottom);
            const dimTop = document.getElementById('bannerDimTop');
            const dimLeft = document.getElementById('bannerDimLeft');
            const dimRight = document.getElementById('bannerDimRight');
            const dimBottom = document.getElementById('bannerDimBottom');
            Object.assign(dimTop.style, { left:'0', top:'0', width:'100%', height:y1+'px' });
            Object.assign(dimBottom.style, { left:'0', top:y2+'px', width:'100%', height:Math.max(0, window.innerHeight-y2)+'px' });
            Object.assign(dimLeft.style, { left:'0', top:y1+'px', width:x1+'px', height:Math.max(0,y2-y1)+'px' });
            Object.assign(dimRight.style, { left:x2+'px', top:y1+'px', width:Math.max(0,window.innerWidth-x2)+'px', height:Math.max(0,y2-y1)+'px' });
            const glow = document.getElementById('bannerRepositionGlow');
            Object.assign(glow.style, { left:(rect.left-4)+'px', top:(rect.top-4)+'px', width:(rect.width+8)+'px', height:(rect.height+8)+'px' });
        }

        function startBannerReposition() {
            if (!MindSpaceMedia.has('profileBannerImg')) {
                showCustomAlert('Mag-upload muna ng banner picture bago ito i-reposition.', 'No Banner Picture');
                return;
            }
            const dimmer = document.getElementById('bannerRepositionDimmer');
            const glow = document.getElementById('bannerRepositionGlow');
            if (!dimmer || !glow) return;
            isBannerRepositionMode = true;
            document.body.classList.add('banner-reposition-mode');
            dimmer.hidden = false; glow.hidden = false;
            updateBannerSpotlight();
            window.addEventListener('resize', updateBannerSpotlight);
            window.addEventListener('scroll', updateBannerSpotlight, true);
        }

        function finishBannerReposition() {
            if (!isBannerRepositionMode) return;
            isBannerRepositionMode = false;
            isDraggingBanner = false;
            document.getElementById('bannerDisplay').classList.remove('dragging');
            document.body.classList.remove('banner-reposition-mode');
            window.removeEventListener('resize', updateBannerSpotlight);
            window.removeEventListener('scroll', updateBannerSpotlight, true);
            try { localStorage.setItem('bannerPosY', String(bannerPosY)); } catch (_) {}
        }

        function initBannerReposition() {
            const banner = document.getElementById('bannerDisplay');
            banner.style.backgroundPositionY = `${bannerPosY}%`;

            banner.addEventListener('pointerdown', (e) => {
                if (!isBannerRepositionMode) return;
                if (e.pointerType === 'mouse' && e.button !== 0) return;
                if (!MindSpaceMedia.has('profileBannerImg')) return;
                isDraggingBanner = true;
                startY = e.clientY;
                banner.classList.add('dragging');
                try { banner.setPointerCapture(e.pointerId); } catch (_) {}
            });

            banner.addEventListener('pointermove', (e) => {
                if (!isDraggingBanner) return;
                const deltaY = e.clientY - startY;
                startY = e.clientY;
                const overflow = getBannerOverflow(banner);
                if (overflow <= 0) return;
                // dragging the picture down reveals its top part => position % goes down
                bannerPosY -= (deltaY / overflow) * 100;
                bannerPosY = Math.max(0, Math.min(100, bannerPosY));
                banner.style.backgroundPositionY = `${bannerPosY}%`;
                updateBannerSpotlight();
            });

            const endDrag = () => {
                if (!isDraggingBanner) return;
                isDraggingBanner = false;
                banner.classList.remove('dragging');
                localStorage.setItem('bannerPosY', bannerPosY);
            };
            banner.addEventListener('pointerup', endDrag);
            banner.addEventListener('pointercancel', endDrag);
        }

        // ---------- PROFILE PICTURE CROP / ZOOM EDITOR ----------
        const crop = { img: null, S: 260, base: 1, zoom: 1, ox: 0, oy: 0, pointers: new Map(), pinchDist: 0, gridTimer: null };

        function cropClamp() {
            const w = crop.img.naturalWidth * crop.base * crop.zoom;
            const h = crop.img.naturalHeight * crop.base * crop.zoom;
            crop.ox = Math.min(0, Math.max(crop.S - w, crop.ox));
            crop.oy = Math.min(0, Math.max(crop.S - h, crop.oy));
        }

        // v1.87: transform lang (walang layout recalculation) = mas smooth sa phone
        function cropRender() {
            const el = document.getElementById('cropImg');
            const scale = crop.base * crop.zoom;
            el.style.transform = `translate3d(${crop.ox}px, ${crop.oy}px, 0) scale(${scale})`;
        }

        // Grid: lalabas habang nag-a-adjust, mawawala pagkatapos ng konting sandali
        function cropShowGrid(hold) {
            const g = document.getElementById('cropGrid');
            if (!g) return;
            g.classList.add('show');
            clearTimeout(crop.gridTimer);
            if (!hold) crop.gridTimer = setTimeout(() => g.classList.remove('show'), 900);
        }
        function cropHideGridSoon() {
            clearTimeout(crop.gridTimer);
            crop.gridTimer = setTimeout(() => {
                const g = document.getElementById('cropGrid');
                if (g) g.classList.remove('show');
            }, 700);
        }

        // Change zoom around a focus point (default: gitna ng circle)
        function cropSetZoom(newZoom, fx, fy) {
            if (!crop.img) return;
            if (fx == null) fx = crop.S / 2;
            if (fy == null) fy = crop.S / 2;
            newZoom = Math.max(1, Math.min(4, newZoom));
            const oldScale = crop.base * crop.zoom;
            const ix = (fx - crop.ox) / oldScale;
            const iy = (fy - crop.oy) / oldScale;
            crop.zoom = newZoom;
            const newScale = crop.base * crop.zoom;
            crop.ox = fx - ix * newScale;
            crop.oy = fy - iy * newScale;
            cropClamp();
            document.getElementById('cropZoom').value = crop.zoom;
            cropRender();
            cropShowGrid(crop.pointers.size > 0);
        }

        async function openAvatarCropper(file) {
            let dataUrl, img;
            try {
                dataUrl = await fileToDataURL(file);
                img = await loadImageEl(dataUrl);
            } catch (e) {
                showCustomAlert('Could not open that image. Please choose another one.', 'Invalid Image');
                return;
            }
            crop.img = img;
            crop.pointers.clear();
            crop.pinchDist = 0;
            const el = document.getElementById('cropImg');
            el.src = dataUrl;
            el.style.width = img.naturalWidth + 'px';
            el.style.height = img.naturalHeight + 'px';
            document.getElementById('avatarCropModal').classList.add('active');

            const stage = document.getElementById('cropStage');
            crop.S = stage.clientWidth;                          // clientWidth = loob na ng border, kaya walang bawas
            crop.base = crop.S / Math.min(img.naturalWidth, img.naturalHeight);
            crop.zoom = 1;
            crop.ox = (crop.S - img.naturalWidth * crop.base) / 2;
            crop.oy = (crop.S - img.naturalHeight * crop.base) / 2;
            document.getElementById('cropZoom').value = 1;
            cropRender();
            cropShowGrid();                                      // saglit na grid pagbukas
        }

        function closeAvatarCropper() {
            document.getElementById('avatarCropModal').classList.remove('active');
            document.getElementById('logoInput').value = '';
            crop.pointers.clear();
            clearTimeout(crop.gridTimer);
            const g = document.getElementById('cropGrid');
            if (g) g.classList.remove('show');
            crop.img = null;
        }

        async function saveAvatarCrop() {
            if (!crop.img) return;
            const OUT = 400, k = OUT / crop.S, scale = crop.base * crop.zoom;
            const canvas = document.createElement('canvas');
            canvas.width = canvas.height = OUT;
            const ctx = canvas.getContext('2d');
            ctx.fillStyle = '#ffffff';
            ctx.fillRect(0, 0, OUT, OUT);
            ctx.drawImage(crop.img, crop.ox * k, crop.oy * k, crop.img.naturalWidth * scale * k, crop.img.naturalHeight * scale * k);
            const result = canvas.toDataURL('image/jpeg', 0.9);
            if (!(await safeStore('profileLogoImg', result))) return;
            document.getElementById('profileImage').src = result;
            invalidateMindSpaceStartupWarm('feed', 'journal', 'bible');
            updateMediaControls();
            closeAvatarCropper();
        }

        function initAvatarCropperEvents() {
            const stage = document.getElementById('cropStage');
            const local = (x, y) => {
                const r = stage.getBoundingClientRect();
                return { x: x - r.left - stage.clientLeft, y: y - r.top - stage.clientTop };
            };

            stage.addEventListener('pointerdown', (e) => {
                if (!crop.img || crop.pointers.size >= 2) return;
                e.preventDefault();
                crop.pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
                try { stage.setPointerCapture(e.pointerId); } catch (_) {}
                if (crop.pointers.size === 2) {
                    const [a, b] = [...crop.pointers.values()];
                    crop.pinchDist = Math.hypot(a.x - b.x, a.y - b.y);
                }
                cropShowGrid(true);
            });

            stage.addEventListener('pointermove', (e) => {
                if (!crop.img || !crop.pointers.has(e.pointerId)) return;
                e.preventDefault();
                const prev = crop.pointers.get(e.pointerId);
                if (crop.pointers.size === 1) {
                    crop.ox += e.clientX - prev.x;
                    crop.oy += e.clientY - prev.y;
                    crop.pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
                    cropClamp();
                    cropRender();
                    cropShowGrid(true);
                } else if (crop.pointers.size === 2) {
                    const [a0, b0] = [...crop.pointers.values()];
                    const prevMid = { x: (a0.x + b0.x) / 2, y: (a0.y + b0.y) / 2 };
                    crop.pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
                    const [a, b] = [...crop.pointers.values()];
                    const mid = { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 };
                    const dist = Math.hypot(a.x - b.x, a.y - b.y);
                    crop.ox += mid.x - prevMid.x;                 // pan gamit ang dalawang daliri
                    crop.oy += mid.y - prevMid.y;
                    const f = local(mid.x, mid.y);
                    if (crop.pinchDist > 0) cropSetZoom(crop.zoom * (dist / crop.pinchDist), f.x, f.y);
                    else { cropClamp(); cropRender(); }
                    crop.pinchDist = dist;
                    cropShowGrid(true);
                }
            });

            const release = (e) => {
                crop.pointers.delete(e.pointerId);
                crop.pinchDist = 0;
                try { stage.releasePointerCapture(e.pointerId); } catch (_) {}
                if (crop.pointers.size === 0) cropHideGridSoon();
            };
            stage.addEventListener('pointerup', release);
            stage.addEventListener('pointercancel', release);
            stage.addEventListener('lostpointercapture', release);

            stage.addEventListener('wheel', (e) => {
                if (!crop.img) return;
                e.preventDefault();
                const f = local(e.clientX, e.clientY);
                cropSetZoom(crop.zoom * (e.deltaY < 0 ? 1.08 : 1 / 1.08), f.x, f.y);
            }, { passive: false });

            const slider = document.getElementById('cropZoom');
            slider.addEventListener('input', (e) => {
                if (crop.img) cropSetZoom(parseFloat(e.target.value));
            });
            const sliderDown = () => { if (crop.img) cropShowGrid(true); };
            const sliderUp = () => { if (crop.img) cropHideGridSoon(); };
            slider.addEventListener('pointerdown', sliderDown);
            slider.addEventListener('pointerup', sliderUp);
            slider.addEventListener('pointercancel', sliderUp);

            // Kapag nag-rotate / nag-resize ang phone, i-adjust ang sukat para hindi mag-iba ang crop
            window.addEventListener('resize', () => {
                if (!crop.img) return;
                const nS = stage.clientWidth;
                if (!nS || nS === crop.S) return;
                const r = nS / crop.S;
                crop.base *= r; crop.ox *= r; crop.oy *= r; crop.S = nS;
                cropClamp(); cropRender();
            });
        }

        function initImageUploads() {
            initAvatarCropperEvents();

            // Profile picture -> open the move/zoom editor first, save only after pressing Save
            document.getElementById('logoInput').onchange = function (e) {
                const file = e.target.files[0];
                if (file) openAvatarCropper(file);
            };

            // Banner -> downsized so it fits in browser storage, then can be dragged to reposition
            document.getElementById('bannerInput').onchange = async function (e) {
                const file = e.target.files[0];
                e.target.value = '';
                if (!file) return;
                try {
                    const img = await loadImageEl(await fileToDataURL(file));
                    const s = Math.min(1, 1600 / img.naturalWidth);
                    const canvas = document.createElement('canvas');
                    canvas.width = Math.round(img.naturalWidth * s);
                    canvas.height = Math.round(img.naturalHeight * s);
                    const ctx = canvas.getContext('2d');
                    ctx.fillStyle = '#ffffff';
                    ctx.fillRect(0, 0, canvas.width, canvas.height);
                    ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
                    const result = canvas.toDataURL('image/jpeg', 0.85);
                    if (!(await safeStore('profileBannerImg', result))) return;
                    bannerImgRatio = canvas.height / canvas.width;
                    bannerPosY = 50;
                    localStorage.setItem('bannerPosY', bannerPosY);
                    const banner = document.getElementById('bannerDisplay');
                    banner.style.backgroundImage = `url(${result})`;
                    banner.style.backgroundPositionY = '50%';
                    updateMediaControls();
                } catch (err) {
                    showCustomAlert('Could not open that image. Please choose another one.', 'Invalid Image');
                }
            };
        }

