        function updateThemeToggleState() {
            const root = document.documentElement;
            const themeBtn = document.getElementById('themeBtn');
            if (!themeBtn) return;
            const glassActive = currentThemeColorKey === 'glass' && root.getAttribute('data-color-theme') === 'glass' && root.getAttribute('data-theme') !== 'dark';
            themeBtn.disabled = glassActive;
            themeBtn.setAttribute('aria-disabled', glassActive ? 'true' : 'false');
            themeBtn.title = glassActive ? 'Night Mode is unavailable while Liquid Glass is active' : 'Toggle Night Mode';
        }

        function getSystemTheme() {
            try { return window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light'; }
            catch (_) { return 'light'; }
        }
        function getThemeMode() {
            try {
                const mode = localStorage.getItem('appThemeMode');
                if (mode === 'dark' || mode === 'light' || mode === 'system') return mode;
                // Migrate the old saved app choice; do not mistake manual Light Mode for System Mode.
                const legacyMode = localStorage.getItem('appTheme');
                if (legacyMode === 'dark' || legacyMode === 'light') {
                    localStorage.setItem('appThemeMode', legacyMode);
                    return legacyMode;
                }
                return 'system';
            } catch (_) { return 'system'; }
        }
        function updateThemeModeButtons() {
            const root = document.documentElement;
            const themeBtn = document.getElementById('themeBtn');
            const systemBtn = document.getElementById('systemThemeBtn');
            const activeTheme = root.getAttribute('data-theme') === 'dark' ? 'dark' : 'light';
            const mode = getThemeMode();
            if (themeBtn) {
                themeBtn.innerHTML = activeTheme === 'dark'
                    ? `<i class="fa-solid fa-sun"></i> <span class="tab-label">Light Mode</span>`
                    : `<i class="fa-solid fa-moon"></i> <span class="tab-label">Night Mode</span>`;
                themeBtn.title = 'Manually switch between Light Mode and Night Mode';
            }
            if (systemBtn) {
                const systemOn = mode === 'system';
                const deviceTheme = getSystemTheme();
                systemBtn.innerHTML = `<i class="fa-solid fa-circle-half-stroke"></i> <span class="tab-label">System Theme: ${systemOn ? 'ON' : 'OFF'}</span>`;
                systemBtn.title = `System Theme ${systemOn ? 'ON' : 'OFF'} — device is ${deviceTheme}; tap to ${systemOn ? 'turn off and keep the current app theme' : 'follow the device theme'}`;
                systemBtn.setAttribute('aria-pressed', systemOn ? 'true' : 'false');
            }
        }
        function applyThemeMode(mode, showPreview = false) {
            const root = document.documentElement;
            const validMode = mode === 'dark' || mode === 'light' ? mode : 'system';
            let resolvedTheme = validMode === 'system' ? getSystemTheme() : validMode;
            // Liquid Glass remains a light-only color theme in this app.
            if (currentThemeColorKey === 'glass') resolvedTheme = 'light';
            const currentTheme = root.getAttribute('data-theme') === 'dark' ? 'dark' : 'light';
            const preview = showPreview && resolvedTheme !== currentTheme && !themeModePreviewActive
                ? showThemeModePreview(resolvedTheme) : null;
            if (preview) themeModePreviewActive = true;
            const apply = () => {
                // Resolve again at apply-time in case the phone changed theme during the preview.
                let finalTheme = validMode === 'system' ? getSystemTheme() : validMode;
                if (currentThemeColorKey === 'glass') finalTheme = 'light';
                root.setAttribute('data-theme', finalTheme);
                root.style.colorScheme = finalTheme + ' only';
                applyThemeColor(currentThemeColorKey);
                updateThemeModeButtons();
                updateStatusBarColor();
                updateThemeToggleState();
            };
            if (!preview) { apply(); return; }
            const setProgress = value => {
                const percent = Math.max(0, Math.min(100, Math.round(value)));
                const progress = preview.querySelector('.theme-preview-progress');
                const track = preview.querySelector('.theme-preview-progress-track');
                const fill = preview.querySelector('.theme-preview-progress-fill');
                if (progress) progress.textContent = `${percent}%`;
                if (track) track.setAttribute('aria-valuenow', String(percent));
                if (fill) fill.style.width = `${percent}%`;
            };
            setProgress(12);
            requestAnimationFrame(() => {
                setProgress(35);
                requestAnimationFrame(() => {
                    apply();
                    setProgress(100);
                    window.setTimeout(() => {
                        preview.classList.add('closing');
                        window.setTimeout(() => {
                            preview.remove();
                            themeModePreviewActive = false;
                        }, 760);
                    }, 3000);
                });
            });
        }
        function setThemeMode(mode, showPreview = false) {
            const validMode = mode === 'dark' || mode === 'light' ? mode : 'system';
            try { localStorage.setItem('appThemeMode', validMode); } catch (_) {}
            applyThemeMode(validMode, showPreview);
        }
        function toggleSystemTheme() {
            if (getThemeMode() === 'system') {
                // OFF freezes the app at the currently displayed light/dark appearance.
                setThemeMode(document.documentElement.getAttribute('data-theme') === 'dark' ? 'dark' : 'light', false);
            } else {
                // ON follows the phone; show a preview first if the actual app appearance changes.
                setThemeMode('system', true);
            }
        }
        function syncDeviceThemeButton() {
            document.documentElement.setAttribute('data-device-theme', getSystemTheme());
            updateThemeModeButtons();
        }
        let themeModePreviewActive = false;
        function toggleTheme(showPreview = true) {
            const root = document.documentElement;
            const currentTheme = root.getAttribute('data-theme');
            const themeBtn = document.getElementById('themeBtn');
            if (currentThemeColorKey === 'glass' && root.getAttribute('data-color-theme') === 'glass') {
                updateThemeToggleState();
                return;
            }
            if (showPreview && themeModePreviewActive) return;

            const nextTheme = currentTheme === 'dark' ? 'light' : 'dark';
            const preview = showPreview ? showThemeModePreview(nextTheme) : null;
            if (preview) themeModePreviewActive = true;

            const applyMode = () => {
                try {
                    localStorage.setItem('appThemeMode', nextTheme);
                    localStorage.setItem('appTheme', nextTheme); // backward compatibility with older versions
                } catch (_) {}
                root.setAttribute('data-theme', nextTheme);
                root.style.colorScheme = nextTheme + ' only';
                applyThemeColor(currentThemeColorKey);
                updateThemeModeButtons();
                updateStatusBarColor();
                updateThemeToggleState();
            };

            if (!preview) {
                applyMode();
                return;
            }

            const setProgress = value => {
                const percent = Math.max(0, Math.min(100, Math.round(value)));
                const progress = preview.querySelector('.theme-preview-progress');
                const track = preview.querySelector('.theme-preview-progress-track');
                const fill = preview.querySelector('.theme-preview-progress-fill');
                if (progress) progress.textContent = `${percent}%`;
                if (track) track.setAttribute('aria-valuenow', String(percent));
                if (fill) fill.style.width = `${percent}%`;
            };
            setProgress(12);
            /* Ipakita muna ang preview bago ilapat ang mode sa ilalim nito. */
            requestAnimationFrame(() => {
                setProgress(35);
                requestAnimationFrame(() => {
                    applyMode();
                    setProgress(100);
                    window.setTimeout(() => {
                        preview.classList.add('closing');
                        window.setTimeout(() => {
                            preview.remove();
                            themeModePreviewActive = false;
                        }, 760);
                    }, 3000);
                });
            });
        }

        function loadTheme() {
            // Existing installs without the new preference now follow the phone's system theme.
            applyThemeMode(getThemeMode());
        }
        try {
            const systemThemeQuery = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)');
            if (systemThemeQuery) {
                const onSystemThemeChange = () => {
                    // The button always mirrors the device; the app changes only when System Theme is ON.
                    document.documentElement.setAttribute('data-device-theme', getSystemTheme());
                    updateThemeModeButtons();
                    if (getThemeMode() === 'system') applyThemeMode('system', true);
                };
                if (systemThemeQuery.addEventListener) systemThemeQuery.addEventListener('change', onSystemThemeChange);
                else if (systemThemeQuery.addListener) systemThemeQuery.addListener(onSystemThemeChange);
            }
        } catch (_) {}
        function escapeHtml(text) {
            if (!text) return "";
            return text
                .replace(/&/g, "&amp;")
                .replace(/</g, "&lt;")
                .replace(/>/g, "&gt;")
                .replace(/"/g, "&quot;")
                .replace(/'/g, "&#039;");
        }

        function refreshSubjectDropdowns() {
            const addSelect = document.getElementById('subjectCategoryInput');
            const testFilter = document.getElementById('practiceFilterSubject');
            const rightFilter = document.getElementById('rightPanelSubjectFilter');

            const prevTestVal = testFilter.value;
            const prevRightVal = rightFilter.value;

            addSelect.innerHTML = subjectsList.map(s => `<option value="${escapeHtml(s)}">${escapeHtml(s)}</option>`).join('');

            const filterOptionsHTML = `<option value="ALL">-- All Subjects --</option>` + 
                subjectsList.map(s => `<option value="${escapeHtml(s)}">${escapeHtml(s)}</option>`).join('');

            testFilter.innerHTML = filterOptionsHTML;
            rightFilter.innerHTML = `<option value="ALL">All Subjects</option>` + 
                subjectsList.map(s => `<option value="${escapeHtml(s)}">${escapeHtml(s)}</option>`).join('');

            if (subjectsList.includes(prevTestVal)) testFilter.value = prevTestVal;
            if (subjectsList.includes(prevRightVal)) rightFilter.value = prevRightVal;
        }

