            jCard.parentNode.insertBefore(jTrig, jCard); bindTrigger(jTrig, 'journal');
            const jp = createPopup('journal', [jCard]);
            jp.editing = () => editingJournalIndex >= 0; jp.cancel = () => cancelEditJournal();

