        function bsitGetQuestionBank() { return bsitSelectedTopic === 'general' ? GENERAL_QUESTION_BANK : bsitSelectedTopic === 'grammar' ? ENGLISH_GRAMMAR_QUESTION_BANK : BSIT_QUIZ_BANK; }
